**Harnessing the Power of Scripting for Complex Test Scenarios:**

**Why Groovy in SoapUI?**
Groovy is a dynamic language that runs on the Java Virtual Machine (JVM). It provides powerful scripting capabilities to extend SoapUI functionality beyond standard features.

**Script Locations in SoapUI:**

1. **TestSuite Scripts:** Setup/teardown for entire suite
2. **TestCase Scripts:** Setup/teardown for individual test cases
3. **TestStep Scripts:** Custom logic within test steps
4. **Assertion Scripts:** Custom validation logic
5. **MockService Scripts:** Dynamic response generation
6. **Event Handlers:** Custom actions on events

**Groovy Script Context Objects:**

```groovy
// Available variables in any SoapUI Groovy script
log.info("Logging with built-in logger")  // Logging

// Test context
context.setProperty("key", "value")  // Store in context
String value = context.getProperty("key")  // Retrieve

// Test runner
testRunner.gotoStepByName("SomeStep")  // Navigate
testRunner.fail("Test failed")  // Fail test
testRunner.cancel("Cancelled")  // Cancel

// Test case
def testCase = testRunner.testCase
testCase.setPropertyValue("prop", "value")

// Message exchange (in test steps)
String request = messageExchange.requestContent
String response = messageExchange.responseContent
int statusCode = messageExchange.responseHeaders["#status#"][0].toInteger()

// Project
def project = testCase.testSuite.project
project.setPropertyValue("baseUrl", "https://api.example.com")
```

**Common Groovy Script Examples:**

**1. Request Manipulation:**
```groovy
// Modify request before sending
import groovy.json.JsonSlurper
import groovy.json.JsonOutput

// Parse request if it exists
if (messageExchange.requestContent) {
    def requestJson = new JsonSlurper().parseText(messageExchange.requestContent)

    // Add timestamp to request
    requestJson.timestamp = new Date().time

    // Modify fields
    requestJson.username = requestJson.username.toLowerCase()

    // Convert back to JSON and update request
    messageExchange.setRequestContent(JsonOutput.toJson(requestJson))

    log.info "Request modified: ${JsonOutput.prettyPrint(messageExchange.requestContent)}"
}
```

**2. Response Processing:**
```groovy
// Extract and store data from response
import groovy.json.JsonSlurper

def responseJson = new JsonSlurper().parseText(messageExchange.responseContent)

// Extract values
String userId = responseJson.user.id
String authToken = responseJson.token

// Store in test case properties
testRunner.testCase.setPropertyValue("createdUserId", userId)
testRunner.testCase.setPropertyValue("authToken", authToken)

// Store in context for immediate use
context.setProperty("userId", userId)

log.info "User ID ${userId} extracted and stored"

// Additional validation
assert responseJson.user.status == "active"
assert responseJson.user.email != null
```

**3. Conditional Logic:**
```groovy
// Run different steps based on conditions
String userRole = context.expand('${#TestCase#userRole}')

if (userRole == "admin") {
    log.info "Admin user - running admin-specific steps"
    testRunner.runTestStepByName("AdminPermissionsTest")
} else if (userRole == "manager") {
    log.info "Manager user - checking manager permissions"
    testRunner.runTestStepByName("ManagerPermissionsTest")
} else {
    log.info "Regular user - running basic permissions test"
    testRunner.runTestStepByName("BasicPermissionsTest")
}

// Based on response status
if (messageExchange.responseHeaders["#status#"][0] == "200") {
    testRunner.runTestStepByName("SuccessValidation")
} else {
    testRunner.fail("Expected 200 but got ${messageExchange.responseHeaders["#status#"][0]}")
}
```

**4. Data Generation:**
```groovy
import java.text.SimpleDateFormat
import java.util.Random

// Generate random data
Random rand = new Random()

String generateUsername() {
    return "user_${rand.nextInt(10000)}_${System.currentTimeMillis()}"
}

String generateEmail(String username) {
    return "${username}@test.com"
}

String generateDate() {
    def sdf = new SimpleDateFormat("yyyy-MM-dd'T'HH:mm:ss'Z'")
    sdf.setTimeZone(TimeZone.getTimeZone("UTC"))
    return sdf.format(new Date())
}

// Set generated data
testRunner.testCase.setPropertyValue("newUsername", generateUsername())
testRunner.testCase.setPropertyValue("newEmail", generateEmail(context.getProperty("newUsername")))
testRunner.testCase.setPropertyValue("timestamp", generateDate())

log.info "Generated: ${testRunner.testCase.getPropertyValue('newUsername')}"
```

**5. File Operations:**
```groovy
import java.nio.file.*

// Read file content
String content = new File(context.expand('${projectDir}') + "/data/config.json").text

// Parse configuration
def config = new groovy.json.JsonSlurper().parseText(content)

// Write test results
File resultsFile = new File(context.expand('${projectDir}') + "/output/results.txt")
resultsFile.append("Test run at ${new Date()}\n")
resultsFile.append("Response time: ${messageExchange.timeTaken}ms\n")
resultsFile.append("Status: ${messageExchange.responseHeaders["#status#"][0]}\n")

// Read CSV data
Files.lines(Paths.get(context.expand('${projectDir}') + "/data/users.csv")).each { line ->
    String[] parts = line.split(',')
    log.info "User: ${parts[0]}, ${parts[1]}"
}
```

**6. Database Operations:**
```groovy
import groovy.sql.Sql

// Database connection
def dbUrl = "jdbc:mysql://localhost:3306/testdb"
def dbUser = "testuser"
def dbPass = "testpass"
def dbDriver = "com.mysql.jdbc.Driver"

def sql = Sql.newInstance(dbUrl, dbUser, dbPass, dbDriver)

// Query data
def userId = context.expand('${#TestCase#userId}')

def row = sql.firstRow("SELECT * FROM users WHERE id = ?", [userId.toInteger()])

if (row) {
    log.info "User found: ${row.username}"
    testRunner.testCase.setPropertyValue("dbUsername", row.username)
    testRunner.testCase.setPropertyValue("dbEmail", row.email)
} else {
    log.warn "User ${userId} not found in database"
}

// Insert test record
sql.execute("INSERT INTO test_results (test_name, status, run_date) VALUES (?, ?, ?)", 
    ["UserRegistration", "PASSED", new Date()])

sql.close()
```

**7. Custom Assertions:**
```groovy
// Complex validation script
import groovy.json.JsonSlurper

def responseJson = new JsonSlurper().parseText(messageExchange.responseContent)

// Check multiple conditions
assert responseJson.status == "success" : "Status should be success"
assert responseJson.data != null : "Data should not be null"
assert responseJson.data.size() > 0 : "Data array should not be empty"

// Validate each item
def expectedIds = context.expand('${#Project#expectedUserIds}').split(',')
responseJson.data.eachWithIndex { user, index ->
    assert user.id.toString() == expectedIds[index] : "ID mismatch at index ${index}"
    assert user.email.contains('@') : "Invalid email at index ${index}"
    assert user.created != null : "Missing creation date at index ${index}"
}

// Check response time
assert messageExchange.timeTaken < 2000 : "Response too slow: ${messageExchange.timeTaken}ms"

log.info "All custom assertions passed"
```

**8. External API Calls:**
```groovy
import groovyx.net.http.HTTPBuilder
import static groovyx.net.http.ContentType.JSON

def http = new HTTPBuilder('https://api.example.com')

// Call external service for validation
http.request(com.example.service.Method.GET, JSON) {
    uri.path = '/validate'
    uri.query = [token: context.expand('${#TestCase#authToken}')]

    response.success = { resp, json ->
        log.info "Validation successful: ${json}"
        assert json.valid == true
        context.setProperty('validationResult', json.message)
    }

    response.failure = { resp ->
        log.error "Validation failed: ${resp.statusLine}"
        testRunner.fail("External validation failed")
    }
}
```

**9. Performance Monitoring:**
```groovy
// Track performance metrics
long startTime = System.currentTimeMillis()

// Execute step (or steps)
testRunner.runTestStepByName("HeavyOperation")

long endTime = System.currentTimeMillis()
long duration = endTime - startTime

// Store metrics
context.setProperty("operationDuration", duration.toString())

def metricsFile = new File(context.expand('${projectDir}') + "/performance.log")
metricsFile.append("${new Date()},HeavyOperation,${duration}ms\n")

// Check performance threshold
assert duration < 5000 : "Operation took too long: ${duration}ms"

log.info "Performance: ${duration}ms"
```

**10. Error Handling:**
```groovy
import org.apache.log4j.Logger

try {
    // Risky operation
    def json = new groovy.json.JsonSlurper().parseText(messageExchange.responseContent)

    if (!json.success) {
        throw new Exception("API returned failure: ${json.message}")
    }

} catch (Exception e) {
    log.error "Error processing response: ${e.message}"

    // Log to file
    def errorLog = new File(context.expand('${projectDir}') + "/errors.log")
    errorLog.append("${new Date()}: ${e.message}\n")

    // Take screenshot if UI mode
    if (!testRunner.getRunningContext().getExpandableContext().get("headless")) {
        com.eviware.soapui.support.UISupport.showErrorMessage(e.message)
    }

    // Decide whether to continue
    if (e.message.contains("critical")) {
        throw e  // Re-throw to fail test
    } else {
        log.warn "Continuing despite error"
    }
}
```

**Script Optimization Tips:**

1. **Cache Reusable Objects:**
```groovy
