This complete example demonstrates how a well-designed mock service can support development and testing for a real-world e-commerce application, handling complex scenarios while maintaining realistic behavior.

content.explanation:
**When Built-in Assertions Aren't Enough:**

Groovy scripting allows you to create custom assertions for complex validation scenarios that built-in assertions can't handle.

**Script Assertion Context:**

When you create a script assertion, SoapUI provides several variables:

| Variable | Description | Example |
|----------|-------------|---------|
| `log` | Logger for output | `log.info "Validating response"` |
| `context` | Test context (shared data) | `context.getProperty("userId")` |
| `testRunner` | Test execution control | `testRunner.fail("Test failed")` |
| `messageExchange` | Request/response data | `messageExchange.responseContent` |
| `assert` | Assertion method | `assert response.contains("success")` |

**Basic Script Assertion Examples:**

```groovy
// Simple validation
assert messageExchange.responseContent.contains("success") : "Response missing 'success'"

// Parse JSON and validate
import groovy.json.JsonSlurper

def json = new JsonSlurper().parseText(messageExchange.responseContent)
assert json.id != null : "ID is missing"
assert json.name.length() > 0 : "Name is empty"
assert json.email.contains('@') : "Invalid email format"
```

**Advanced Custom Assertions:**

**1. Multi-Field Validation:**

```groovy
import groovy.json.JsonSlurper

def json = new JsonSlurper().parseText(messageExchange.responseContent)

// Validate all required fields exist
def requiredFields = ['id', 'name', 'email', 'createdAt', 'status']
requiredFields.each { field ->
    assert json[field] != null : "Missing required field: ${field}"
}

// Validate data types
assert json.id instanceof Integer : "ID should be integer"
assert json.name instanceof String : "Name should be string"
assert json.status in ['active', 'inactive', 'pending'] : "Invalid status"

// Validate email format
assert json.email ==~ /.+@.+\..+/ : "Invalid email format"

// Validate timestamp is recent (within last hour)
import java.text.SimpleDateFormat

def dateFormat = new SimpleDateFormat("yyyy-MM-dd'T'HH:mm:ssXXX")
def createdAt = dateFormat.parse(json.createdAt)
def now = new Date()
def oneHourAgo = new Date(now.time - 3600000)

assert createdAt.after(oneHourAgo) : "createdAt should be within the last hour"
assert createdAt.before(now) : "createdAt should be in the past"

log.info "All custom validations passed"
```

**2. Cross-Field Validation:**

```groovy
import groovy.json.JsonSlurper

def json = new JsonSlurper().parseText(messageExchange.responseContent)

// Validate that start date is before end date
if (json.startDate && json.endDate) {
    def start = Date.parse("yyyy-MM-dd", json.startDate)
    def end = Date.parse("yyyy-MM-dd", json.endDate)
    assert start.before(end) : "Start date must be before end date"
}

// Validate that total equals sum of items
if (json.items && json.total) {
    def calculatedTotal = json.items.sum { it.price * it.quantity }
    assert Math.abs(calculatedTotal - json.total) < 0.01 : 
        "Total ${json.total} doesn't match calculated ${calculatedTotal}"
}

// Validate that at least one payment method is selected
if (json.paymentMethods) {
    def hasSelectedMethod = json.paymentMethods.any { it.selected }
    assert hasSelectedMethod : "At least one payment method must be selected"
}
```

**3. Array Validation:**

```groovy
import groovy.json.JsonSlurper

def json = new JsonSlurper().parseText(messageExchange.responseContent)

// Validate array properties
assert json.users instanceof List : "users should be an array"
assert json.users.size() > 0 : "users array should not be empty"

// Validate each element in array
json.users.eachWithIndex { user, index ->
    assert user.id != null : "User ${index} missing ID"
    assert user.name != null : "User ${index} missing name"
    assert user.email.contains('@') : "User ${index} has invalid email"
}

// Check for duplicates
def uniqueIds = json.users.collect { it.id }.unique()
assert uniqueIds.size() == json.users.size() : "Duplicate user IDs found"

// Sort validation
def sortedNames = json.users.collect { it.name }.sort()
assert sortedNames == json.users.collect { it.name } : "Users should be sorted by name"
```

**4. Business Logic Validation:**

```groovy
import groovy.json.JsonSlurper

def json = new JsonSlurper().parseText(messageExchange.responseContent)

// Validate discount rules
if (json.order && json.order.items) {
    def total = json.order.items.sum { it.price * it.quantity }
    def discount = json.order.discount ?: 0
    def finalTotal = json.order.finalTotal

    // Validate discount amount
    if (total > 1000) {
        assert discount >= total * 0.1 : "Orders over $1000 should get at least 10% discount"
    }

    // Validate final total calculation
    assert Math.abs((total - discount) - finalTotal) < 0.01 : 
        "Final total calculation incorrect"
}

// Validate inventory rules
json.items.each { item ->
    if (item.quantity > item.available) {
        log.warn "Item ${item.id}: quantity ${item.quantity} exceeds available ${item.available}"
    }
}
```

**5. Regular Expression Validation:**

```groovy
import groovy.json.JsonSlurper

def json = new JsonSlurper().parseText(messageExchange.responseContent)

// Define validation patterns
def patterns = [
    email: /.+@.+\..+/,
    phone: /^\+?[0-9\-\s]{10,}$/,
    zipCode: /^[0-9]{5}(-[0-9]{4})?$/,
    username: /^[a-zA-Z0-9_]{3,20}$/,
    date: /^\d{4}-\d{2}-\d{2}$/,
    uuid: /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/
]

// Validate fields against patterns
json.users.each { user ->
    assert (user.email =~ patterns.email) : "Invalid email: ${user.email}"
    assert (user.phone =~ patterns.phone) : "Invalid phone: ${user.phone}"
    assert (user.username =~ patterns.username) : "Invalid username: ${user.username}"
}
```

**6. Date and Time Validation:**

```groovy
import java.text.SimpleDateFormat

def response = messageExchange.responseContent
def json = new groovy.json.JsonSlurper().parseText(response)

// Validate date formats
def dateFormat = new SimpleDateFormat("yyyy-MM-dd'T'HH:mm:ssXXX")

json.events.each { event ->
    try {
        def date = dateFormat.parse(event.timestamp)

        // Check if date is not in future
        assert date.before(new Date()) : "Event timestamp cannot be in future"

        // Check if dates are in sequence
        if (event.previousTimestamp) {
            def prevDate = dateFormat.parse(event.previousTimestamp)
            assert prevDate.before(date) : "Previous timestamp must be before current"
        }
    } catch (Exception e) {
        assert false : "Invalid date format: ${event.timestamp}"
    }
}
```

**7. Numeric Validation:**

```groovy
import groovy.json.JsonSlurper

def json = new JsonSlurper().parseText(messageExchange.responseContent)

// Validate numeric ranges
json.products.each { product ->
    assert product.price > 0 : "Price must be positive"
    assert product.price < 1000000 : "Price seems unreasonably high"
    assert product.stock >= 0 : "Stock cannot be negative"

    // Validate price precision (max 2 decimal places)
    def priceString = product.price.toString()
    if (priceString.contains('.')) {
        def decimals = priceString.split('\.')[1].length()
        assert decimals <= 2 : "Price should have at most 2 decimal places"
    }
}

// Validate percentages
json.discounts.each { discount ->
    assert discount.percentage >= 0 : "Discount cannot be negative"
    assert discount.percentage <= 100 : "Discount cannot exceed 100%"
}
```

**8. Error Handling in Script Assertions:**

```groovy
// Robust script assertion with error handling
try {
    def json = new groovy.json.JsonSlurper().parseText(messageExchange.responseContent)

    // Your validation logic here
    assert json.status == "success" : "Status should be success"
    assert json.data != null : "Data should not be null"

    log.info "All validations passed"

} catch (Exception e) {
    log.error "Validation failed: ${e.message}"
    throw new AssertionError("Script assertion failed: ${e.message}")
}
```

**9. Dynamic Expected Values:**

```groovy
import groovy.json.JsonSlurper

def json = new JsonSlurper().parseText(messageExchange.responseContent)

// Get expected values from properties
def expectedId = context.expand('${#TestCase#expectedId}').toInteger()
def expectedName = context.expand('${#TestCase#expectedName}')

assert json.id == expectedId : "ID mismatch"
assert json.name == expectedName : "Name mismatch"

// Calculate expected value
if (json.order && json.order.items) {
    def calculatedTotal = json.order.items.sum { it.price * it.quantity }
    def taxRate = context.expand('${#Project#taxRate}').toDouble()
    def expectedTotal = calculatedTotal * (1 + taxRate)

    assert Math.abs(json.order.total - expectedTotal) < 0.01 : 
        "Total should be ${expectedTotal} but was ${json.order.total}"
}
```

**10. Custom Assertion Library:**

```groovy
// Reusable validation functions
def validateEmail(email) {
    return email ==~ /.+@.+\..+/
}

def validateDate(dateString, format = "yyyy-MM-dd") {
    try {
        Date.parse(format, dateString)
        return true
    } catch (Exception e) {
        return false
    }
}

def validateNumericRange(value, min, max) {
    return value >= min && value <= max
}

def validateArrayLength(array, min, max) {
    return array.size() >= min && array.size() <= max
}

// Use in assertion
import groovy.json.JsonSlurper

def json = new JsonSlurper().parseText(messageExchange.responseContent)

assert validateEmail(json.email) : "Invalid email format"
