```groovy
import java.text.SimpleDateFormat
import java.util.concurrent.atomic.AtomicLong

// Generate realistic test data
def generateTestData() {
    def data = [:]

    // Timestamps
    def now = new Date()
    def sdf = new SimpleDateFormat("yyyy-MM-dd'T'HH:mm:ss'Z'")
    sdf.setTimeZone(TimeZone.getTimeZone("UTC"))

    data.timestamp = sdf.format(now)
    data.startDate = sdf.format(now - 7*24*60*60*1000) // 7 days ago
    data.endDate = sdf.format(now + 7*24*60*60*1000)   // 7 days from now

    // Unique IDs with counters
    def counter = context.getProperty('idCounter')
    if (!counter) {
        counter = new AtomicLong(1000)
        context.setProperty('idCounter', counter)
    }

    data.userId = "USR${counter.getAndIncrement()}"
    data.orderId = "ORD${counter.getAndIncrement()}"

    // Random data
    def random = new Random()
    data.age = 18 + random.nextInt(82)
    data.score = random.nextInt(101)
    data.price = 10 + (random.nextDouble() * 990)

    // Select from lists
    def countries = ['US', 'UK', 'CA', 'AU', 'DE', 'FR', 'JP']
    def roles = ['admin', 'user', 'manager', 'guest']

    data.country = countries[random.nextInt(countries.size())]
    data.role = roles[random.nextInt(roles.size())]

    // Format currency
    data.formattedPrice = String.format("$%.2f", data.price)

    return data
}

def testData = generateTestData()
testData.each { key, value ->
    testRunner.testCase.setPropertyValue(key, value.toString())
