**2. Request/Response Manipulation:**

```groovy
// Pre-request script - modify request before sending
import groovy.json.JsonSlurper
import groovy.json.JsonOutput

// Parse current request
if (messageExchange.requestContent) {
    def requestJson = new JsonSlurper().parseText(messageExchange.requestContent)

    // Add timestamp
    requestJson.timestamp = new Date().time

    // Add request ID
    requestJson.requestId = UUID.randomUUID().toString()

    // Sign request (example)
    def signature = calculateSignature(requestJson)
    requestJson.signature = signature

    // Convert back to JSON
    def modifiedRequest = JsonOutput.toJson(requestJson)
    messageExchange.setRequestContent(modifiedRequest)

    log.info "Request modified with signature: ${signature}"
}

// Helper function
def calculateSignature(data) {
    def input = data.sort().collect { k, v -> "${k}=${v}" }.join('&')
    return java.net.URLEncoder.encode(input, 'UTF-8')
}
