**4. External Service Integration:**

```groovy
@Grab('org.apache.httpcomponents:httpclient:4.5.14')
import org.apache.http.client.methods.HttpGet
import org.apache.http.impl.client.HttpClients
import org.apache.http.util.EntityUtils

def callExternalService(endpoint, params = [:]) {
    def client = HttpClients.createDefault()

    // Build URL with parameters
    def urlBuilder = new StringBuilder(endpoint)
    if (params) {
        urlBuilder.append('?')
        params.eachWithIndex { key, value, index ->
            if (index > 0) urlBuilder.append('&')
            urlBuilder.append(URLEncoder.encode(key, 'UTF-8'))
                    .append('=')
                    .append(URLEncoder.encode(value.toString(), 'UTF-8'))
        }
    }

    def request = new HttpGet(urlBuilder.toString())
    request.setHeader('User-Agent', 'SoapUI-Groovy')

    try {
        def response = client.execute(request)
        def content = EntityUtils.toString(response.getEntity())
        def statusCode = response.getStatusLine().getStatusCode()

        return [
            status: statusCode,
            content: content,
            success: statusCode >= 200 && statusCode < 300
        ]
    } finally {
        client.close()
    }
}

// Call external validation service
def result = callExternalService('https://api.example.com/validate', [
    token: context.expand('${authToken}'),
    action: 'verify'
