**10. Complete Groovy Script Library Example:**

```groovy
// TestUtilities.groovy - Reusable functions
class TestUtilities {

    static def parseJsonResponse(messageExchange) {
        def response = messageExchange.responseContent
        if (!response) return null
        return new groovy.json.JsonSlurper().parseText(response)
    }

    static def parseXmlResponse(messageExchange) {
        def response = messageExchange.responseContent
        if (!response) return null
        return new groovy.xml.XmlSlurper().parseText(response)
    }

    static def generateTimestamp() {
        return new Date().format("yyyy-MM-dd'T'HH:mm:ss'Z'", TimeZone.getTimeZone('UTC'))
    }

    static def generateUUID() {
        return UUID.randomUUID().toString()
    }

    static def calculateResponseStats(times) {
        if (!times || times.isEmpty()) return null

        def sorted = times.sort()
        return [
            avg: times.sum() / times.size(),
            min: sorted[0],
            max: sorted[-1],
            median: sorted[sorted.size().intdiv(2)],
            p95: sorted[(int)(sorted.size() * 0.95)],
            count: times.size()
        ]
    }

    static def assertRange(value, min, max, message = "Value out of range") {
        assert value >= min && value <= max : 
            "${message}: ${value} not in [${min}, ${max}]"
    }

    static def assertMatches(value, pattern, message = "Pattern mismatch") {
        assert (value =~ pattern) : "${message}: '${value}' doesn't match ${pattern}"
    }
}

