            case '2.0':
                return 'Modern Response'
            case '3.0-beta':
                return 'Beta Response'
        }
    }

    // User-agent based responses
    if (userAgent) {
        if (userAgent.contains('Mobile')) {
            return 'Mobile Optimized Response'
        }
        if (userAgent.contains('bot') || userAgent.contains('crawler')) {
            return 'SEO Response'
        }
    }

    // Authentication-based responses
    if (!authToken) {
        return 'Unauthorized Response'
    }

    // Token validation
    if (authToken.startsWith('Bearer ')) {
        def token = authToken.substring(7)
        if (isValidToken(token)) {
            def role = getRoleFromToken(token)
            switch(role) {
                case 'admin':
                    return 'Admin Response'
                case 'user':
                    return 'User Response'
                default:
                    return 'Guest Response'
            }
        }
    }

    return 'Default Response'
}

