            log.warn "Cleanup failed: ${e.message}"
        }
    }
}

// Register cleanup to run at end
testRunner.testCase.addTearDownScript(cleanup)
```

**4. Validation with Clear Messages:**

```groovy
// GOOD: Clear, specific error messages
def json = new groovy.json.JsonSlurper().parseText(messageExchange.responseContent)
assert json.id != null : "Response missing 'id' field. Full response: ${messageExchange.responseContent}"
assert json.status == 'active' : "Expected status 'active' but got '${json.status}'"

// BAD: Vague error message
assert json != null  // Fails without explanation
```

**5. Graceful Degradation:**

```groovy
// Handle optional fields gracefully
def json = new groovy.json.JsonSlurper().parseText(messageExchange.responseContent)

// Optional field - log warning, don't fail
if (json.notes == null) {
    log.warn "Optional field 'notes' is missing"
}

// Provide default if missing
def timeout = json.timeout ?: 30

// Conditional validation
if (json.requiredField == null) {
    testRunner.fail("Required field 'requiredField' is missing")
}
```

**6. Error Logging Best Practices:**

```groovy
// Log enough information to debug
log.error "=== Test Failure Details ==="
log.error "Step: ${testRunner.currentStep.name}"
log.error "Request: ${messageExchange.requestContent}"
log.error "Response: ${messageExchange.responseContent}"
log.error "Status: ${messageExchange.responseHeaders['#status#'][0]}"
log.error "Time: ${messageExchange.timeTaken}ms"

// Log to file for analysis
def logFile = new File(context.expand('${projectDir}') + '/failure.log')
logFile.append("${new Date()}: ${testRunner.testCase.name} - ${e.message}\n")
```

**7. Error Recovery Strategies:**

```groovy
// Recover and continue where possible
try {
    testRunner.runTestStepByName("Critical Step")
} catch (Exception e) {
    log.error "Critical step failed, but continuing with remaining tests"
    // Mark as failed but continue
    testRunner.fail(e.message, false) // false = don't abort
}
```

**8. Timeout Handling:**

```groovy
// Handle timeouts gracefully
def executeWithTimeout(Closure operation, int timeoutSeconds) {
    def thread = Thread.start {
        operation()
    }

    thread.join(timeoutSeconds * 1000)

    if (thread.isAlive()) {
        thread.interrupt()
        throw new Exception("Operation timed out after ${timeoutSeconds} seconds")
    }
}
```

**9. Comprehensive Error Handling Example:**

```groovy
<testStep name="Comprehensive Error Handling" type="groovy">
  <script>
    <![CDATA[
      import groovy.json.JsonSlurper

      def logContext = [:]
      logContext.testCase = testRunner.testCase.name
      logContext.timestamp = new Date().format("yyyy-MM-dd HH:mm:ss")

      try {
        // Execute test step
        log.info "Starting test execution"
        def response = testRunner.runTestStepByName("Create User")

        // Validate response
        def json = new JsonSlurper().parseText(response)

        assert json.id != null : "No ID returned"
        assert json.status == 'active' : "Status should be active"

        // Store for cleanup
        context.setProperty('createdUserId', json.id.toString())

        log.info "Test completed successfully"

      } catch (AssertionError e) {
        // Expected assertion failure
        log.error "Assertion failed: ${e.message}"
        log.error "Response: ${messageExchange.responseContent}"

        // Write to failure log
        def logFile = new File(context.expand('${projectDir}') + '/failures.log')
        logFile.append("${logContext.timestamp},${logContext.testCase},ASSERTION,${e.message}\n")

        testRunner.fail(e.message)

      } catch (SocketTimeoutException e) {
        // Timeout
        log.error "Request timed out"
        log.error "Endpoint: ${context.expand('${#Project#apiUrl}')}"

        testRunner.fail("Request timed out after ${context.expand('${#Project#timeout}')}ms")

      } catch (Exception e) {
        // Unexpected error
        log.error "Unexpected error: ${e.message}"
        log.error "Stack trace: ${e.stackTrace}"

        testRunner.fail("Test failed: ${e.message}")

      } finally {
        // Always clean up
        def userId = context.getProperty('createdUserId')
        if (userId) {
          try {
            def deleteStep = testRunner.testCase.getTestStepByName("Delete User")
            deleteStep.setPropertyValue('userId', userId)
            deleteStep.run(testRunner, context)
            log.info "Cleaned up user ${userId}"
          } catch (Exception e) {
            log.warn "Cleanup failed: ${e.message}"
          }
        }
      }
    ]]>
  </script>
</testStep>
```

**10. Error Handling Best Practices:**

✅ **Be Specific:** Catch specific exceptions, not just Exception
✅ **Log Context:** Include test name, data, request/response
✅ **Clean Up:** Always clean up, even on failure
✅ **Fail Fast:** Stop on critical failures
✅ **Continue When Safe:** For non-critical failures
✅ **Clear Messages:** Explain what went wrong and why
✅ **Retry Flaky Operations:** But know when to give up
✅ **Monitor Error Patterns:** Track common failures
✅ **Document Recovery:** Note what cleanup is needed

**11. Error Handling Anti-Patterns:**

❌ **Empty Catch Blocks:** `catch (Exception e) { }` - hides errors
❌ **Swallowing Exceptions:** Logging but not failing
❌ **Ignoring Cleanup:** Leaving test data behind
❌ **Vague Messages:** "Error occurred" - no context
❌ **Too Broad Catching:** Catching Exception everywhere
❌ **No Retry for Flaky:** Tests that randomly fail
❌ **No Timeout:** Tests that hang forever

**12. Error Handling Checklist:**

✅ Try-catch around risky operations
✅ Specific exception types caught
✅ Cleanup in finally block
✅ Clear error messages with context
✅ Failures logged to file
✅ Retry logic for flaky operations
✅ Timeouts configured
✅ Abort on critical failures
✅ Continue on non-critical
✅ Error metrics tracked
✅ Regular review of failures

**How Appium Achieves True Cross-Platform Testing:**

Appium's cross-platform capability is its killer feature. Here's how it works:

**1. Unified API**

```
Same commands, different platforms:

// Android - find by ID
driver.findElement(By.id("com.example.app:id/login_button"));

// iOS - find by accessibility ID
driver.findElement(By.id("login_button"));

Same method name, different platforms, same result!
```

**2. Platform-Specific Adaptations**

While the API is unified, Appium handles platform differences internally:

```
// You write:
driver.swipe(100, 500, 100, 200, 1000);

// Appium translates to:
Android: UiAutomator2 swipe command
iOS: XCUITest swipe with coordinates

// You write:
driver.findElement(By.xpath("//*[@text='Login']"));

// Appium translates to:
Android: UiAutomator2 XPath engine
iOS: XCUITest XPath engine
```

**3. Platform-Specific Features**

When you need platform-specific functionality, Appium provides access:

```java
// Android-specific
if (driver.isAndroid()) {
    driver.findElement(By.AndroidUIAutomator(
        "new UiScrollable(new UiSelector().scrollable(true)).scrollIntoView(" +
        "new UiSelector().text('Login'))"
    ));
}

// iOS-specific
if (driver.isIOS()) {
    driver.findElement(By.iOSNsPredicateString(
        "type == 'XCUIElementTypeButton' AND name == 'Login'"
    ));
}
```

**4. Same Test, Different Platforms**

```java
public class LoginTest {

    @Test
    public void testValidLogin() {
        // Same code works on both platforms!

        // Find and enter username
        WebElement username = driver.findElement(By.id("username"));
        username.sendKeys("testuser");

        // Find and enter password
        WebElement password = driver.findElement(By.id("password"));
        password.sendKeys("pass123");

        // Click login
        WebElement loginButton = driver.findElement(By.id("loginButton"));
        loginButton.click();

        // Verify success
        WebElement welcome = driver.findElement(By.id("welcomeMessage"));
        assertTrue(welcome.isDisplayed());
    }
}
```

**5. Handling Platform Differences**

Sometimes you need platform-specific code:

```java
public void enterText(String fieldName, String text) {
    if (driver.isAndroid()) {
        // Android approach
        driver.findElement(By.id("com.app:id/" + fieldName)).sendKeys(text);
    } else {
        // iOS approach - different ID structure
        driver.findElement(By.id(fieldName)).sendKeys(text);
    }
}
```

**6. Cross-Platform Test Strategy**

```
Optimal Cross-Platform Testing:

Write 80% common code:
├── Login flows
├── Navigation
├── Form filling
└── Logout flows

Keep 20% platform-specific:
├── Android back button
├── iOS home indicator
├── Platform-specific gestures
└── OS-specific dialogs
```

**7. Benefits of Cross-Platform Testing**

| Benefit | Impact |
|---------|--------|
| **Code Reuse** | 80% less code to maintain |
| **Faster Development** | Write once, test twice |
| **Consistent Testing** | Same scenarios on both platforms |
| **Easier Maintenance** | One change fixes both |
| **Lower Cost** | Half the test development effort |
| **Faster Time to Market** | Ship both platforms together |

