**1. Setup and Capabilities**

```java
import io.appium.java_client.AppiumDriver;
import io.appium.java_client.android.AndroidDriver;
import io.appium.java_client.ios.IOSDriver;
import org.junit.After;
import org.junit.Before;
import org.junit.Test;
import org.openqa.selenium.remote.DesiredCapabilities;
import java.net.URL;

public class CrossPlatformLoginTest {

    private AppiumDriver driver;
    private boolean isAndroid;

    @Before
    public void setUp() throws Exception {
        DesiredCapabilities caps = new DesiredCapabilities();

        // Set platform - change this for different platforms
        String platform = System.getProperty("platform", "Android");

        if (platform.equals("Android")) {
            caps.setCapability("platformName", "Android");
            caps.setCapability("platformVersion", "12.0");
            caps.setCapability("deviceName", "Pixel 5");
            caps.setCapability("app", "/path/to/app.apk");
            caps.setCapability("automationName", "UiAutomator2");
            driver = new AndroidDriver(new URL("http://localhost:4723"), caps);
            isAndroid = true;
        } else {
            caps.setCapability("platformName", "iOS");
            caps.setCapability("platformVersion", "15.0");
            caps.setCapability("deviceName", "iPhone 13");
            caps.setCapability("app", "/path/to/app.app");
            caps.setCapability("automationName", "XCUITest");
            driver = new IOSDriver(new URL("http://localhost:4723"), caps);
            isAndroid = false;
        }
    }

    @After
    public void tearDown() {
        if (driver != null) {
            driver.quit();
        }
    }

    @Test
    public void testValidLogin() {
        // Find and enter username - works on both platforms!
        WebElement usernameField = waitForElement(By.id("username"));
        usernameField.sendKeys("testuser");

        // Find and enter password
        WebElement passwordField = waitForElement(By.id("password"));
        passwordField.sendKeys("pass123");

        // Hide keyboard (platform-specific)
        hideKeyboard();

        // Click login button
        WebElement loginButton = waitForElement(By.id("loginButton"));
        loginButton.click();

        // Verify success
        WebElement welcomeMessage = waitForElement(By.id("welcomeMessage"));
        assertTrue(welcomeMessage.isDisplayed());
        assertEquals("Welcome, testuser!", welcomeMessage.getText());
    }

    private WebElement waitForElement(By locator) {
        // Wait up to 10 seconds for element
        return driver.findElement(locator);
    }

    private void hideKeyboard() {
        if (isAndroid) {
            // Android: press back button
            driver.navigate().back();
        } else {
            // iOS: use hideKeyboard command
            driver.hideKeyboard();
        }
    }
}
```

