        caps.setCapability("platformName", props.getProperty("platform.name"));
        caps.setCapability("appium:deviceName", getDeviceName());
        caps.setCapability("appium:platformVersion", getPlatformVersion());
        caps.setCapability("appium:app", getAppPath());
        caps.setCapability("appium:automationName", props.getProperty("automation.name"));
        // Add all capabilities from properties file
        return caps;
    }
}

