**6. Error Handling and Recovery**

```java
public class TestBase {
    protected AppiumDriver driver;
    protected TestWatcher watcher = new TestWatcher() {
        @Override
        protected void failed(Throwable e, Description description) {
            takeScreenshot(description.getMethodName());
            savePageSource(description.getMethodName());
            logFailure(description, e);
        }
    };

    @Rule
    public TestWatcher getWatcher() {
        return watcher;
    }

    private void takeScreenshot(String testName) {
        File screenshot = ((TakesScreenshot) driver).getScreenshotAs(OutputType.FILE);
        String path = "screenshots/" + testName + "_" + timestamp() + ".png";
        try {
            FileUtils.copyFile(screenshot, new File(path));
            System.out.println("Screenshot saved: " + path);
        } catch (IOException e) {
            System.err.println("Failed to save screenshot: " + e.getMessage());
        }
    }

    private void savePageSource(String testName) {
        String pageSource = driver.getPageSource();
        String path = "pagesource/" + testName + "_" + timestamp() + ".xml";
        try {
            FileUtils.writeStringToFile(new File(path), pageSource, StandardCharsets.UTF_8);
        } catch (IOException e) {
            System.err.println("Failed to save page source: " + e.getMessage());
        }
    }
}
```

