**2. Common Gesture Helpers**

```java
public class GestureUtils {

    public static void swipe(AppiumDriver driver, Direction direction) {
        Dimension size = driver.manage().window().getSize();
        int startX, startY, endX, endY;

        switch (direction) {
            case UP:
                startX = size.width / 2;
                startY = (int) (size.height * 0.7);
                endX = size.width / 2;
                endY = (int) (size.height * 0.3);
                break;
            case DOWN:
                startX = size.width / 2;
                startY = (int) (size.height * 0.3);
                endX = size.width / 2;
                endY = (int) (size.height * 0.7);
                break;
            case LEFT:
                startX = (int) (size.width * 0.8);
                startY = size.height / 2;
                endX = (int) (size.width * 0.2);
                endY = size.height / 2;
                break;
            case RIGHT:
                startX = (int) (size.width * 0.2);
                startY = size.height / 2;
                endX = (int) (size.width * 0.8);
                endY = size.height / 2;
                break;
            default:
                throw new IllegalArgumentException("Unknown direction: " + direction);
        }

        swipe(driver, startX, startY, endX, endY);
    }

    public static void swipe(AppiumDriver driver, int startX, int startY, int endX, int endY) {
        PointerInput finger = new PointerInput(PointerInput.Kind.TOUCH, "finger");
        Sequence swipe = new Sequence(finger, 0);

        swipe.addAction(finger.createPointerMove(Duration.ZERO, 
            PointerInput.Origin.viewport(), startX, startY));
        swipe.addAction(finger.createPointerDown(PointerInput.MouseButton.LEFT.asArg()));
        swipe.addAction(finger.createPointerMove(Duration.ofMillis(500), 
            PointerInput.Origin.viewport(), endX, endY));
        swipe.addAction(finger.createPointerUp(PointerInput.MouseButton.LEFT.asArg()));

        driver.perform(Collections.singletonList(swipe));
    }

    public static void tap(AppiumDriver driver, int x, int y) {
        PointerInput finger = new PointerInput(PointerInput.Kind.TOUCH, "finger");
        Sequence tap = new Sequence(finger, 1);

        tap.addAction(finger.createPointerMove(Duration.ZERO, 
            PointerInput.Origin.viewport(), x, y));
        tap.addAction(finger.createPointerDown(PointerInput.MouseButton.LEFT.asArg()));
        tap.addAction(finger.createPointerUp(PointerInput.MouseButton.LEFT.asArg()));

        driver.perform(Collections.singletonList(tap));
    }

    public static void longPress(AppiumDriver driver, int x, int y, int duration) {
        PointerInput finger = new PointerInput(PointerInput.Kind.TOUCH, "finger");
        Sequence longPress = new Sequence(finger, 1);

        longPress.addAction(finger.createPointerMove(Duration.ZERO, 
            PointerInput.Origin.viewport(), x, y));
        longPress.addAction(finger.createPointerDown(PointerInput.MouseButton.LEFT.asArg()));
        longPress.addAction(new Pause(finger, Duration.ofMillis(duration)));
        longPress.addAction(finger.createPointerUp(PointerInput.MouseButton.LEFT.asArg()));

        driver.perform(Collections.singletonList(longPress));
    }

    public static void pinchAndZoom(AppiumDriver driver, boolean zoomIn) {
        Dimension size = driver.manage().window().getSize();
        int centerX = size.width / 2;
        int centerY = size.height / 2;

        PointerInput finger1 = new PointerInput(PointerInput.Kind.TOUCH, "finger1");
        PointerInput finger2 = new PointerInput(PointerInput.Kind.TOUCH, "finger2");

        Sequence sequence1 = new Sequence(finger1, 0);
        Sequence sequence2 = new Sequence(finger2, 1);

        if (zoomIn) {
            // Fingers move apart
            sequence1.addAction(finger1.createPointerMove(Duration.ZERO, 
                PointerInput.Origin.viewport(), centerX - 100, centerY));
            sequence2.addAction(finger2.createPointerMove(Duration.ZERO, 
                PointerInput.Origin.viewport(), centerX + 100, centerY));
        } else {
            // Fingers move together
            sequence1.addAction(finger1.createPointerMove(Duration.ZERO, 
                PointerInput.Origin.viewport(), centerX - 200, centerY));
            sequence2.addAction(finger2.createPointerMove(Duration.ZERO, 
                PointerInput.Origin.viewport(), centerX + 200, centerY));
        }

        sequence1.addAction(finger1.createPointerDown(PointerInput.MouseButton.LEFT.asArg()));
        sequence2.addAction(finger2.createPointerDown(PointerInput.MouseButton.LEFT.asArg()));

        if (zoomIn) {
            sequence1.addAction(finger1.createPointerMove(Duration.ofMillis(500), 
                PointerInput.Origin.viewport(), centerX - 200, centerY));
            sequence2.addAction(finger2.createPointerMove(Duration.ofMillis(500), 
                PointerInput.Origin.viewport(), centerX + 200, centerY));
        } else {
            sequence1.addAction(finger1.createPointerMove(Duration.ofMillis(500), 
                PointerInput.Origin.viewport(), centerX - 100, centerY));
            sequence2.addAction(finger2.createPointerMove(Duration.ofMillis(500), 
                PointerInput.Origin.viewport(), centerX + 100, centerY));
        }

        sequence1.addAction(finger1.createPointerUp(PointerInput.MouseButton.LEFT.asArg()));
        sequence2.addAction(finger2.createPointerUp(PointerInput.MouseButton.LEFT.asArg()));

        driver.perform(Arrays.asList(sequence1, sequence2));
    }

    public enum Direction {
        UP, DOWN, LEFT, RIGHT
    }
}
```

