**2. Dynamic Device Allocation**

```java
public class DeviceManager {
    private static final List<Device> availableDevices = new CopyOnWriteArrayList<>();
    private static final Map<String, Device> usedDevices = new ConcurrentHashMap<>();

    static {
        // Load available devices from config
        availableDevices.addAll(loadDevicesFromConfig());
    }

    @DataProvider(name = "devices", parallel = true)
    public static Object[][] getDevices() {
        List<Object[]> devices = new ArrayList<>();
        for (Device device : availableDevices) {
            devices.add(new Object[]{device});
        }
        return devices.toArray(new Object[0][]);
    }

    public static synchronized Device allocateDevice(String testName) {
        if (availableDevices.isEmpty()) {
            throw new RuntimeException("No devices available");
        }
        Device device = availableDevices.remove(0);
        usedDevices.put(testName, device);
        return device;
    }

    public static synchronized void releaseDevice(String testName) {
        Device device = usedDevices.remove(testName);
        if (device != null) {
            availableDevices.add(device);
        }
    }
}

