```java
public class TestAnalytics {

    public static void analyzeResults(List<ITestResult> results) {
        Map<String, Object> analytics = new HashMap<>();

        // Basic stats
        analytics.put("total", results.size());
        analytics.put("passed", countByStatus(results, ITestResult.SUCCESS));
        analytics.put("failed", countByStatus(results, ITestResult.FAILURE));
        analytics.put("skipped", countByStatus(results, ITestResult.SKIP));

        // Pass rate
        analytics.put("passRate", (double) analytics.get("passed") / results.size() * 100);

        // Duration stats
        double totalDuration = results.stream()
            .mapToLong(ITestResult::getEndMillis - ITestResult::getStartMillis)
            .sum();
        analytics.put("totalDuration", totalDuration / 1000); // seconds

        // Failures by test
        Map<String, Integer> failuresByTest = new HashMap<>();
        results.stream()
            .filter(r -> r.getStatus() == ITestResult.FAILURE)
            .forEach(r -> {
                String testName = r.getMethod().getMethodName();
                failuresByTest.merge(testName, 1, Integer::sum);
            });
        analytics.put("failuresByTest", failuresByTest);

        // Failures by exception type
        Map<String, Integer> failuresByException = new HashMap<>();
        results.stream()
            .filter(r -> r.getStatus() == ITestResult.FAILURE)
            .forEach(r -> {
                String exception = r.getThrowable().getClass().getSimpleName();
                failuresByException.merge(exception, 1, Integer::sum);
            });
        analytics.put("failuresByException", failuresByException);

        // Device performance
        Map<String, List<Long>> deviceTimes = new HashMap<>();
        results.forEach(r -> {
            String device = r.getTestContext().getAttribute("deviceName").toString();
            long duration = r.getEndMillis() - r.getStartMillis();
            deviceTimes.computeIfAbsent(device, k -> new ArrayList<>()).add(duration);
        });

        Map<String, Double> avgDeviceTimes = new HashMap<>();
        deviceTimes.forEach((device, times) -> {
            avgDeviceTimes.put(device, times.stream().mapToLong(l -> l).average().orElse(0));
        });
        analytics.put("avgDeviceTimes", avgDeviceTimes);

        // Save to JSON
        try {
            ObjectMapper mapper = new ObjectMapper();
            mapper.writerWithDefaultPrettyPrinter()
                .writeValue(new File("reports/analytics.json"), analytics);
        } catch (IOException e) {
            e.printStackTrace();
        }
    }
}
