```groovy
// Jenkinsfile with advanced features
pipeline {
    agent any

    tools {
        maven 'Maven 3.8'
        jdk 'JDK 11'
    }

    environment {
        // Set environment based on branch
        KARATE_ENV = (env.BRANCH_NAME == 'main') ? 'staging' : 'dev'

        // Credentials from Jenkins
        API_KEY = credentials('api-key')
        DB_PASSWORD = credentials('db-password')
    }

    parameters {
        choice(
            name: 'TEST_SUITE',
            choices: ['all', 'smoke', 'regression', 'performance'],
            description: 'Which test suite to run'
        )
    }

    stages {
        stage('Checkout') {
            steps {
                checkout scm
            }
        }

        stage('Build') {
            steps {
                sh 'mvn clean compile'
            }
        }

        stage('Run Tests') {
            when {
                expression { params.TEST_SUITE != 'performance' }
            }
            parallel {
                stage('Smoke Tests') {
                    when {
                        expression { params.TEST_SUITE in ['all', 'smoke'] }
                    }
                    steps {
                        sh 'mvn test -Dtest=SmokeTestRunner -Dkarate.env=${KARATE_ENV}'
                    }
                }
                stage('Regression Tests') {
                    when {
                        expression { params.TEST_SUITE in ['all', 'regression'] }
                    }
                    steps {
                        sh 'mvn test -Dtest=RegressionTestRunner -Dkarate.env=${KARATE_ENV}'
                    }
                }
            }
        }

        stage('Performance Tests') {
            when {
                expression { params.TEST_SUITE == 'performance' && env.BRANCH_NAME == 'main' }
            }
            steps {
                sh 'mvn test -Dtest=PerformanceTestRunner -Dkarate.env=staging'
            }
        }

        stage('Publish Reports') {
            steps {
                junit 'target/surefire-reports/*.xml'
                publishHTML([
                    reportDir: 'target/karate-reports',
                    reportFiles: 'karate-summary.html',
                    reportName: 'Karate Test Report'
                ])
            }
        }
    }

    post {
        always {
            archiveArtifacts artifacts: 'target/karate-reports/**'
            cleanWs()
        }
        success {
            slackSend(
                color: 'good',
                message: "✅ Karate tests passed: ${env.JOB_NAME} - ${env.BUILD_NUMBER}"
            )
        }
        failure {
            slackSend(
                color: 'danger',
                message: "❌ Karate tests failed: ${env.JOB_NAME} - ${env.BUILD_NUMBER}"
            )
        }
    }
}
