import org.testng.*;
import java.io.*;

public class CustomReporter implements IReporter {
    @Override
    public void generateReport(List<XmlSuite> xmlSuites, List<ISuite> suites,
                               String outputDirectory) {
        try (PrintWriter writer = new PrintWriter(outputDirectory + "/custom-report.html")) {
            writer.println("<html><body>");
            writer.println("<h1>Custom Test Report</h1>");

            for (ISuite suite : suites) {
                writer.println("<h2>Suite: " + suite.getName() + "</h2>");

                for (ISuiteResult result : suite.getResults().values()) {
                    ITestContext context = result.getTestContext();
                    writer.println("<h3>Tests: " + context.getName() + "</h3>");
                    writer.println("<p>Passed: " + context.getPassedTests().size() + "</p>");
                    writer.println("<p>Failed: " + context.getFailedTests().size() + "</p>");
                }
            }
            writer.println("</body></html>");
        } catch (IOException e) {
            e.printStackTrace();
        }
    }
}
