**12. Automated Locator Health Checks**

```java
public class LocatorHealthCheck {

    @Test
    public void verifyAllLocators() {
        LoginPage loginPage = new LoginPage(driver);

        // Test each locator
        assertLocatorWorks(loginPage.USERNAME_INPUT, "Should find username field");
        assertLocatorWorks(loginPage.PASSWORD_INPUT, "Should find password field");
        assertLocatorWorks(loginPage.LOGIN_BUTTON, "Should find login button");

        // Test uniqueness
        assertLocatorUnique(loginPage.LOGIN_BUTTON);
    }

    private void assertLocatorWorks(By locator, String message) {
        try {
            WebElement element = driver.findElement(locator);
            assertTrue(element.isDisplayed(), message);
        } catch (NoSuchElementException e) {
