**5. Handling Multiple AJAX Calls**

```java
public class MultiAjaxHandler {
    private WebDriver driver;
    private Map<String, Integer> requestCounts = new HashMap<>();

    public void waitForAllAjax(int expectedRequests) {
        WebDriverWait wait = new WebDriverWait(driver, 10);

        wait.until(driver -> {
            JavascriptExecutor js = (JavascriptExecutor) driver;

            // Get current request count
            Long activeRequests = (Long) js.executeScript(
                "return window.XMLHttpRequest ? window.XMLHttpRequest.active : 0"
            );

            // Store historical data
            String key = String.valueOf(System.currentTimeMillis() / 1000);
            requestCounts.put(key, activeRequests.intValue());

            // Clean up old entries
            cleanupOldEntries();

            // Check if requests have stabilized
            return activeRequests == 0 && hasStabilized();
        });
    }

    private boolean hasStabilized() {
        if (requestCounts.size() < 3) return false;

        List<Integer> recent = new ArrayList<>(requestCounts.values());
        int last3 = recent.subList(recent.size() - 3, recent.size())
            .stream()
            .mapToInt(Integer::intValue)
            .sum();

        return last3 == 0;
    }

    private void cleanupOldEntries() {
        long oneMinuteAgo = (System.currentTimeMillis() - 60000) / 1000;
        requestCounts.entrySet().removeIf(e -> 
            Long.parseLong(e.getKey()) < oneMinuteAgo
        );
    }
}
