public class PopupManager {
    private WebDriver driver;
    private List<PopupHandler> handlers = new ArrayList<>();

    public void registerPopup(By triggerLocator, PopupHandler handler) {
        handlers.add(handler);

        // Set up listener for popup
        ((JavascriptExecutor) driver).executeScript(
            "var observer = new MutationObserver(function(mutations) {" +
            "    mutations.forEach(function(mutation) {" +
            "        if (mutation.addedNodes.length > 0) {" +
            "            window.popupTriggered = true;" +
            "        }" +
            "    });" +
            "});" +
            "observer.observe(document.body, { childList: true, subtree: true });"
        );
    }

    public void handlePopups() {
        WebDriverWait wait = new WebDriverWait(driver, 5);
        try {
            wait.until(driver -> 
                (Boolean) ((JavascriptExecutor) driver)
                    .executeScript("return window.popupTriggered || false")
            );

            for (PopupHandler handler : handlers) {
                if (handler.isVisible()) {
                    handler.handle();
                }
            }
        } catch (TimeoutException e) {
            // No popups appeared
        }
    }
}

interface PopupHandler {
    boolean isVisible();
    void handle();
}
