            List<WebElement> rows = driver.findElements(By.cssSelector("table tbody tr"));
            return rows.size() >= minRows;
        });
    }

    public void waitForTableToRefresh(By tableLocator) {
        // Store initial state
        String initialHtml = driver.findElement(tableLocator).getAttribute("outerHTML");

        // Trigger refresh
        driver.findElement(By.id("refreshTable")).click();

        // Wait for HTML to change
        wait.until(driver -> {
            String currentHtml = driver.findElement(tableLocator).getAttribute("outerHTML");
            return !currentHtml.equals(initialHtml);
        });
    }
}
