**3. Handling Table Pagination**

```java
public class PaginatedTableHandler {
    private WebDriver driver;
    private WebDriverWait wait;

    public PaginatedTableHandler(WebDriver driver) {
        this.driver = driver;
        this.wait = new WebDriverWait(driver, Duration.ofSeconds(10));
    }

    public void goToPage(int pageNumber) {
        // Store first row data to detect change
        String firstRowBefore = getFirstRowData();

        // Click page button
        By pageButton = By.xpath("//div[@class='pagination']//a[text()='" + pageNumber + "']");
        driver.findElement(pageButton).click();

        // Wait for table to update
        wait.until(driver -> {
            String firstRowAfter = getFirstRowData();
            return !firstRowAfter.equals(firstRowBefore);
        });
    }

    private String getFirstRowData() {
        List<WebElement> cells = driver.findElements(
            By.cssSelector("table tbody tr:first-child td")
        );
        return cells.stream()
            .map(WebElement::getText)
            .collect(Collectors.joining("|"));
    }

    public int getTotalPages() {
        List<WebElement> pageLinks = driver.findElements(
            By.cssSelector(".pagination a:not(.next):not(.prev)")
        );
        return pageLinks.size();
    }
}
