**4. Handling Table Filtering**

```java
public class FilterableTableHandler {
    private WebDriver driver;
    private WebDriverWait wait;
    private Map<String, List<String>> dataBeforeFilter;

    public FilterableTableHandler(WebDriver driver) {
        this.driver = driver;
        this.wait = new WebDriverWait(driver, Duration.ofSeconds(10));
    }

    public void applyFilter(String column, String value) {
        // Capture current data
        dataBeforeFilter = captureTableData();

        // Apply filter
        By filterInput = By.xpath("//th[contains(text(), '" + column + "')]/following::input[1]");
        WebElement input = driver.findElement(filterInput);
        input.clear();
        input.sendKeys(value);

        // Trigger filter (may need Enter or wait for debounce)
        input.sendKeys(Keys.ENTER);

        // Wait for results
        waitForFilterResults();
    }

    private void waitForFilterResults() {
        wait.until(driver -> {
            Map<String, List<String>> currentData = captureTableData();
            return !currentData.equals(dataBeforeFilter);
        });

        // Wait for loading indicator if present
        try {
            wait.until(ExpectedConditions.invisibilityOfElementLocated(
                By.className("filter-loading")
            ));
        } catch (TimeoutException e) {
            // No loading indicator
        }
    }

    private Map<String, List<String>> captureTableData() {
        Map<String, List<String>> data = new HashMap<>();
        List<WebElement> headers = driver.findElements(By.cssSelector("table thead th"));
        List<WebElement> rows = driver.findElements(By.cssSelector("table tbody tr"));

        for (int i = 0; i < headers.size(); i++) {
            String header = headers.get(i).getText();
            List<String> columnData = new ArrayList<>();

            for (WebElement row : rows) {
                List<WebElement> cells = row.findElements(By.tagName("td"));
                if (cells.size() > i) {
                    columnData.add(cells.get(i).getText());
                }
            }
            data.put(header, columnData);
        }
        return data;
    }
}
```

