**2. Common Synchronization Patterns**

```java
public class SyncPatterns {
    private WebDriver driver;
    private WebDriverWait wait;

    // Pattern 1: Wait for element then interact
    public void clickWhenReady(By locator) {
        WebElement element = wait.until(
            ExpectedConditions.elementToBeClickable(locator)
        );
        element.click();
    }

    // Pattern 2: Wait for element then get text
    public String getTextWhenVisible(By locator) {
        WebElement element = wait.until(
            ExpectedConditions.visibilityOfElementLocated(locator)
        );
        return element.getText();
    }

    // Pattern 3: Wait for element to disappear
    public void waitForDisappear(By locator) {
        wait.until(ExpectedConditions.invisibilityOfElementLocated(locator));
    }

    // Pattern 4: Wait for attribute value
    public void waitForAttribute(By locator, String attribute, String value) {
        wait.until(ExpectedConditions.attributeToBe(locator, attribute, value));
    }

    // Pattern 5: Wait for text
    public void waitForText(By locator, String text) {
        wait.until(ExpectedConditions.textToBePresentInElementLocated(locator, text));
    }
}
