public class WaitPerformanceMonitor {
    private Map<String, Long> waitTimes = new HashMap<>();

    public <T> T measureWait(String waitName, Supplier<T> waitOperation) {
        long start = System.currentTimeMillis();
        try {
            return waitOperation.get();
        } finally {
            long duration = System.currentTimeMillis() - start;
            waitTimes.put(waitName, duration);
            if (duration > 5000) {
                System.out.println("Slow wait detected: " + waitName + " took " + duration + "ms");
            }
        }
    }

    public void reportWaitTimes() {
        waitTimes.forEach((name, time) -> 
            System.out.println(name + ": " + time + "ms")
        );
    }
}
