public class LeastLoadedBalancer implements LoadBalancer {
    @Override
    public Node selectNode(List<Node> nodes, Capabilities caps) {
        return nodes.stream()
            .filter(n -> n.supports(caps))
            .min(Comparator.comparingInt(Node::getCurrentLoad))
            .orElse(null);
    }
}

public class CapabilityPriorityBalancer implements LoadBalancer {
    @Override
    public Node selectNode(List<Node> nodes, Capabilities caps) {
        // Prefer nodes with exact version match
        return nodes.stream()
            .filter(n -> n.supports(caps))
            .sorted((a, b) -> {
                int aScore = calculateMatchScore(a, caps);
                int bScore = calculateMatchScore(b, caps);
