**1. Quality Gate Definition**

```java
public class QualityGate {
    private final List<GateCondition> conditions;
    private final boolean failBuildOnViolation;

    public QualityGateResult evaluate(TestSuiteResult results) {
        QualityGateResult result = new QualityGateResult();

        for (GateCondition condition : conditions) {
            boolean passed = condition.evaluate(results);
            result.addConditionResult(condition.getName(), passed);

            if (!passed && condition.isCritical()) {
                result.setOverallPassed(false);
                if (failBuildOnViolation) {
                    throw new BuildFailureException(
                        "Quality gate failed: " + condition.getDescription()
                    );
                }
            }
        }

        return result;
    }
}
```

**2. Common Quality Gate Conditions**

```java
// Pass rate gate
public class PassRateGate implements GateCondition {
    private final double minimumPassRate; // e.g., 95%

    public boolean evaluate(TestSuiteResult results) {
        double passRate = (results.getPassedTests() * 100.0) / results.getTotalTests();
        return passRate >= minimumPassRate;
    }
}

// Critical tests gate
public class CriticalTestsGate implements GateCondition {
    private final List<String> criticalTests;

    public boolean evaluate(TestSuiteResult results) {
        for (String criticalTest : criticalTests) {
            if (results.getFailedTests().contains(criticalTest)) {
                return false;
            }
        }
        return true;
    }
}

// Execution time gate
public class ExecutionTimeGate implements GateCondition {
    private final long maxExecutionTime; // milliseconds

    public boolean evaluate(TestSuiteResult results) {
        return results.getTotalDuration() < maxExecutionTime;
    }
}

// Flaky test detection
public class FlakyTestGate implements GateCondition {
    private final int maxFlakyPercentage;
    private final TestHistoryRepository historyRepo;

    public boolean evaluate(TestSuiteResult results) {
        List<String> flakyTests = historyRepo.findFlakyTests(
            results.getTestNames(),
            3,  // At least 3 executions
            20  // More than 20% variance
        );

        double flakyPercentage = (flakyTests.size() * 100.0) / results.getTotalTests();
        return flakyPercentage < maxFlakyPercentage;
    }
}
