public abstract class BaseTest {
    protected WebDriver driver;
    protected TestReporter reporter;
    protected ScreenshotTaker screenshotTaker;

    @BeforeMethod
    public void setUp(Method method) {
        driver = DriverFactory.createDriver(TestConfig.getBrowser());
        driver.manage().window().maximize();
        driver.manage().timeouts().implicitlyWait(0, TimeUnit.SECONDS);

        reporter = new TestReporter(method.getName());
        screenshotTaker = new ScreenshotTaker(driver);

        driver.get(TestConfig.getBaseUrl());
    }

    @AfterMethod
    public void tearDown(ITestResult result) {
        if (result.getStatus() == ITestResult.FAILURE) {
            screenshotTaker.takeScreenshot(result.getName());
            reporter.logFailure(result.getThrowable());
        }

        if (driver != null) {
            driver.quit();
        }

        reporter.save();
    }

    protected <T extends BasePage> T createPage(Class<T> pageClass) {
        try {
            return pageClass.getConstructor(WebDriver.class).newInstance(driver);
        } catch (Exception e) {
            throw new RuntimeException("Failed to create page: " + pageClass, e);
        }
    }
}
