**3. Handling Browser Differences**

```java
public class BrowserCompatibilityHandler {

    private final WebDriver driver;
    private final String browserName;

    public BrowserCompatibilityHandler(WebDriver driver) {
        this.driver = driver;
        this.browserName = getBrowserName();
    }

    private String getBrowserName() {
        if (driver instanceof ChromeDriver) return "chrome";
        if (driver instanceof FirefoxDriver) return "firefox";
        if (driver instanceof EdgeDriver) return "edge";
        if (driver instanceof SafariDriver) return "safari";
        return "unknown";
    }

    public void handleFileUpload(WebElement uploadElement, String filePath) {
        if (browserName.equals("safari")) {
            // Safari handles file upload differently
            uploadElement.sendKeys(filePath);
        } else {
            // Other browsers
            uploadElement.sendKeys(filePath);
        }
    }

    public void handleDatePicker(WebElement dateInput, String date) {
        if (browserName.equals("firefox")) {
            // Firefox needs special handling
            ((JavascriptExecutor) driver).executeScript(
                "arguments[0].removeAttribute('readonly')", dateInput);
            dateInput.clear();
            dateInput.sendKeys(date);
        } else {
            dateInput.sendKeys(date);
        }
    }

    public void handleAlert() {
        if (browserName.equals("safari")) {
            // Safari alert handling
            try {
                driver.switchTo().alert().accept();
            } catch (NoAlertPresentException e) {
                // Safari sometimes throws this
                Thread.sleep(1000);
                driver.switchTo().alert().accept();
            }
        } else {
            driver.switchTo().alert().accept();
        }
    }
}
