```java
public class TestLogger {
    private static final Logger logger = LogManager.getLogger(TestLogger.class);
    private static final ThreadLocal<TestLogContext> context = 
        ThreadLocal.withInitial(TestLogContext::new);

    public static void logInfo(String message) {
        logger.info(formatMessage(message));
        context.get().addLog("INFO", message);
    }

    public static void logError(String message, Throwable error) {
        logger.error(formatMessage(message), error);
        context.get().addLog("ERROR", message + ": " + error.getMessage());
        context.get().setFailed(true);
    }

    public static void logScreenshot(String path) {
        logger.info("Screenshot saved: {}", path);
        context.get().addScreenshot(path);
    }

    public static void logPerformance(String action, long duration) {
        logger.info("PERFORMANCE - {}: {} ms", action, duration);
        context.get().addMetric(action, duration);

        if (duration > 5000) {
            logger.warn("Slow operation detected: {} took {} ms", action, duration);
        }
    }

    private static String formatMessage(String message) {
        return String.format("[%s] [Thread: %s] %s",
            LocalDateTime.now().format(DateTimeFormatter.ISO_LOCAL_TIME),
            Thread.currentThread().getId(),
            message
        );
    }

    @Data
    private static class TestLogContext {
        private List<String> logs = new ArrayList<>();
        private List<String> screenshots = new ArrayList<>();
        private Map<String, Long> metrics = new HashMap<>();
        private boolean failed = false;

        public void addLog(String level, String message) {
            logs.add(String.format("[%s] %s", level, message));
        }

        public void addScreenshot(String path) {
            screenshots.add(path);
        }

        public void addMetric(String action, long duration) {
            metrics.put(action, duration);
        }
    }
}
