**2. Screenshot Strategies**

```java
public class ScreenshotManager {
    private final WebDriver driver;
    private final String screenshotDir;

    public ScreenshotManager(WebDriver driver) {
        this.driver = driver;
        this.screenshotDir = "target/screenshots/";
        new File(screenshotDir).mkdirs();
    }

    public String takeScreenshot(String name) {
        String filename = String.format("%s%s_%s.png",
            screenshotDir,
            name,
            LocalDateTime.now().format(DateTimeFormatter.ofPattern("yyyyMMdd_HHmmss"))
        );

        File screenshot = ((TakesScreenshot) driver).getScreenshotAs(OutputType.FILE);

        try {
            FileUtils.copyFile(screenshot, new File(filename));
            TestLogger.logScreenshot(filename);
            return filename;
        } catch (IOException e) {
            TestLogger.logError("Failed to save screenshot", e);
            return null;
        }
    }

    public String takeElementScreenshot(WebElement element, String name) {
        // Element screenshot (requires additional libraries)
        WrapsDriver wrapsDriver = (WrapsDriver) element;
        File screenshot = ((TakesScreenshot) wrapsDriver.getWrappedDriver())
            .getScreenshotAs(OutputType.FILE);

        // Crop to element
        try {
            BufferedImage fullImg = ImageIO.read(screenshot);
            Point point = element.getLocation();
            int width = element.getSize().getWidth();
            int height = element.getSize().getHeight();

            BufferedImage elementScreenshot = fullImg.getSubimage(
                point.getX(), point.getY(), width, height);
            ImageIO.write(elementScreenshot, "png", screenshot);

            String filename = screenshotDir + "element_" + name + ".png";
            FileUtils.copyFile(screenshot, new File(filename));
            return filename;
        } catch (IOException e) {
            TestLogger.logError("Failed to crop screenshot", e);
            return null;
        }
    }

    public void attachScreenshotToReport(String filename, String title) {
        // Attach to Allure/Extent report
        Allure.addAttachment(title, FileUtils.openInputStream(new File(filename)));
    }
}
