public class TestVideoRecorder {
    private Process ffmpegProcess;
    private String videoPath;

    public void startRecording(String testName) {
        videoPath = "target/videos/" + testName + "_" + 
            System.currentTimeMillis() + ".mp4";

        new File("target/videos/").mkdirs();

        try {
            ProcessBuilder pb = new ProcessBuilder(
                "ffmpeg",
                "-f", "x11grab",
                "-video_size", "1920x1080",
                "-i", ":0.0+0,0",
                "-r", "15",
                videoPath
            );
            ffmpegProcess = pb.start();
        } catch (IOException e) {
            TestLogger.logError("Failed to start video recording", e);
        }
    }

    public void stopRecording() {
        if (ffmpegProcess != null) {
            ffmpegProcess.destroy();
            try {
                ffmpegProcess.waitFor(5, TimeUnit.SECONDS);
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        }
    }
}
