**4. DOM State Capture**

```java
public class DOMSnapshotter {
    private final WebDriver driver;

    public DOMSnapshotter(WebDriver driver) {
        this.driver = driver;
    }

    public void captureDOMState(String name) {
        // Save HTML
        String html = driver.getPageSource();
        saveToFile("target/dom/" + name + "_" + System.currentTimeMillis() + ".html", html);

        // Save console logs
        captureConsoleLogs(name);

        // Save network requests
        captureNetworkLogs(name);

        // Save JavaScript errors
        captureJSErrors(name);
    }

    private void captureConsoleLogs(String name) {
        LogEntries logs = driver.manage().logs().get(LogType.BROWSER);
        StringBuilder logContent = new StringBuilder();

        for (LogEntry entry : logs) {
            logContent.append(entry.getLevel()).append(": ")
                     .append(entry.getMessage()).append("\n");
        }

        saveToFile("target/logs/" + name + "_console.log", logContent.toString());
    }

    private void captureJSErrors(String name) {
        JavascriptExecutor js = (JavascriptExecutor) driver;
        List<String> errors = (List<String>) js.executeScript(
            "var errors = [];" +
            "window.onerror = function(msg, url, line) {" +
            "  errors.push(msg + ' at ' + url + ':' + line);" +
            "  return true;" +
            "};" +
            "return errors;"
        );

        if (!errors.isEmpty()) {
            saveToFile("target/errors/" + name + "_js_errors.log", 
                String.join("\n", errors));
        }
    }
}
