public class EnvironmentManager {

    private static final Map<String, String> baseConfig = new HashMap<>();
    private static final ThreadLocal<Map<String, String>> testConfig = 
        ThreadLocal.withInitial(HashMap::new);

    static {
        // Load base configuration
        try {
            Properties props = new Properties();
            props.load(EnvironmentManager.class.getResourceAsStream(
                "/environment/" + System.getProperty("env", "test") + ".properties"
            ));

            for (String key : props.stringPropertyNames()) {
                baseConfig.put(key, props.getProperty(key));
            }
        } catch (IOException e) {
            throw new RuntimeException("Failed to load environment config", e);
        }
    }

    public static String get(String key) {
        // Test-specific override first
        if (testConfig.get().containsKey(key)) {
            return testConfig.get().get(key);
        }

        // Then base config
        if (baseConfig.containsKey(key)) {
            return baseConfig.get(key);
        }

        // Then system property
        return System.getProperty(key);
    }

    public static void setForTest(String key, String value) {
        testConfig.get().put(key, value);
    }

    public static void clearTestConfig() {
        testConfig.remove();
    }
}
