@SpringBootTest
@ExtendWith({ScreenshotExtension.class, VideoExtension.class})
public abstract class BaseTest {

    @Autowired
    protected WebDriver driver;

    @Autowired
    protected WebDriverWait wait;

    @BeforeEach
    public void setUp() {
        driver.get(TestConfig.getBaseUrl());
        TestDataManager.setupTestData();
    }

    @AfterEach
    public void tearDown(TestInfo testInfo) {
        TestDataManager.cleanupTestData();
        if (driver != null) {
            driver.quit();
        }
    }

    protected <T extends BasePage> T at(Class<T> pageClass) {
        return PageFactory.create(driver, pageClass);
