public class LoginPage extends BasePage {

    @FindBy(css = "[data-testid='username']")
    private WebElement usernameInput;

    @FindBy(css = "[data-testid='password']")
    private WebElement passwordInput;

    @FindBy(css = "[data-testid='login-button']")
    private WebElement loginButton;

    @FindBy(css = "[data-testid='error-message']")
    private WebElement errorMessage;

    public LoginPage(WebDriver driver) {
        super(driver);
    }

    @Override
    public boolean isLoaded() {
        return wait.until(ExpectedConditions.visibilityOf(usernameInput)).isDisplayed();
    }

    public HomePage login(String username, String password) {
        TestLogger.logInfo("Logging in as: " + username);

        usernameInput.sendKeys(username);
        passwordInput.sendKeys(password);
        loginButton.click();

        return new HomePage(driver);
    }

    public String getErrorMessage() {
        return wait.until(ExpectedConditions.visibilityOf(errorMessage)).getText();
    }
