```java
// Java example for ALM REST API

public class ALMConnector {
    private String baseUrl;
    private String cookie;

    public ALMConnector(String url) {
        this.baseUrl = url;
    }

    // Authenticate
    public boolean login(String username, String password) {
        try {
            URL url = new URL(baseUrl + "/api/authentication/sign-in");
            HttpURLConnection conn = (HttpURLConnection) url.openConnection();
            conn.setRequestMethod("POST");
            conn.setRequestProperty("Content-Type", "application/json");
            conn.setDoOutput(true);

            String body = String.format(
                "{\"username\":\"%s\",\"password\":\"%s\"}",
                username, password
            );
            conn.getOutputStream().write(body.getBytes());

            if (conn.getResponseCode() == 200) {
                cookie = conn.getHeaderField("LWSSO_COOKIE_KEY");
                return true;
            }
            return false;
        } catch (Exception e) {
            e.printStackTrace();
            return false;
        }
    }

    // Get test set details
    public String getTestSet(String testSetId) {
        try {
            URL url = new URL(baseUrl + "/api/v2/test-sets/" + testSetId);
            HttpURLConnection conn = (HttpURLConnection) url.openConnection();
            conn.setRequestMethod("GET");
            conn.setRequestProperty("LWSSO_COOKIE_KEY", cookie);

            BufferedReader reader = new BufferedReader(
                new InputStreamReader(conn.getInputStream())
            );
            StringBuilder response = new StringBuilder();
            String line;
            while ((line = reader.readLine()) != null) {
                response.append(line);
            }
            reader.close();

            return response.toString();
        } catch (Exception e) {
            e.printStackTrace();
            return null;
        }
    }
}
```

