**Comprehensive Result Reporting:**

```java
public class ALMReporter {
    private ALMConnector alm;
    private String testRunId;
    private List<TestStepResult> steps;

    public ALMReporter(ALMConnector alm, String testSetId) {
        this.alm = alm;
        this.steps = new ArrayList<>();

        // Create test run
        JSONObject run = new JSONObject();
        run.put("TestSetId", testSetId);
        run.put("StartTime", new Date().toString());
        run.put("Host", InetAddress.getLocalHost().getHostName());

        testRunId = alm.createTestRun(run);
    }

    public void reportStep(String description, String expected, 
                           String actual, boolean passed) {
        TestStepResult step = new TestStepResult();
        step.setDescription(description);
        step.setExpected(expected);
        step.setActual(actual);
        step.setPassed(passed);
        step.setTimestamp(new Date());

        steps.add(step);

        // Send to ALM (batch for performance)
        if (steps.size() >= 10) {
            flushSteps();
        }
    }

    public void reportScreenshot(File screenshot) {
        alm.attachFile(testRunId, screenshot);
    }

    public void reportLog(File logFile) {
        alm.attachFile(testRunId, logFile);
    }

    public void finalizeRun(boolean passed) {
        // Flush remaining steps
        flushSteps();

        // Update run status
        JSONObject update = new JSONObject();
        update.put("Status", passed ? "Passed" : "Failed");
        update.put("EndTime", new Date().toString());
        update.put("TotalSteps", steps.size());

        alm.updateTestRun(testRunId, update);

        // Auto-create defect if failed
        if (!passed) {
            createDefect();
        }
    }

    private void flushSteps() {
        if (steps.isEmpty()) return;

        JSONArray stepsArray = new JSONArray();
        for (TestStepResult step : steps) {
            stepsArray.put(step.toJSON());
        }

        alm.reportSteps(testRunId, stepsArray);
        steps.clear();
    }

    private void createDefect() {
        JSONObject defect = new JSONObject();
        defect.put("Summary", "Selenium test failure: " + testRunId);
        defect.put("Description", buildDefectDescription());
        defect.put("Severity", "Major");
        defect.put("Priority", "High");
        defect.put("LinkedTest", testRunId);

        String defectId = alm.createDefect(defect);

        // Attach evidence
        alm.linkDefectToTestRun(defectId, testRunId);
    }
}
