**6. Automated Token Refresh**

```javascript
// Pre-request script to refresh token

// Check if token exists and is valid
const token = pm.environment.get('accessToken');
const expiresAt = pm.environment.get('tokenExpiresAt');

// If no token or expired, get new one
if (!token || !expiresAt || Date.now() > expiresAt) {
    console.log('Token expired or missing, refreshing...');

    // Make request to get new token
    pm.sendRequest({
        url: pm.environment.get('authUrl') + '/token',
        method: 'POST',
        header: {
            'Content-Type': 'application/json'
        },
        body: {
            mode: 'raw',
            raw: JSON.stringify({
                grant_type: 'client_credentials',
                client_id: pm.environment.get('clientId'),
                client_secret: pm.environment.get('clientSecret')
            })
        }
    }, function(err, res) {
        if (!err) {
            const data = res.json();
            pm.environment.set('accessToken', data.access_token);
            pm.environment.set('tokenExpiresAt', Date.now() + (data.expires_in * 1000));
            console.log('Token refreshed successfully');
        } else {
            console.error('Failed to refresh token:', err);
        }
    });
}
```

**7. Multi-step Authentication**

```javascript
// Complex auth flows

// Step 1: Get CSRF token
pm.sendRequest({
    url: pm.environment.get('baseUrl') + '/csrf-token',
    method: 'GET'
}, function(err, res) {
    if (!err) {
        const csrfToken = res.json().csrfToken;
        pm.environment.set('csrfToken', csrfToken);

        // Step 2: Login with credentials + CSRF
        pm.sendRequest({
            url: pm.environment.get('baseUrl') + '/login',
            method: 'POST',
            header: {
                'X-CSRF-TOKEN': csrfToken
            },
            body: {
                mode: 'raw',
                raw: JSON.stringify({
                    username: pm.environment.get('username'),
                    password: pm.environment.get('password')
                })
            }
        }, function(err2, res2) {
            if (!err2) {
                const sessionToken = res2.json().sessionToken;
                pm.environment.set('sessionToken', sessionToken);
                console.log('Authentication successful');
            }
        });
    }
});
```

