```yaml
name: API Test Pipeline
on:
  push:
    branches: [ main, develop ]
  pull_request:
    branches: [ main ]
  schedule:
    - cron: '0 */6 * * *'  # Every 6 hours

jobs:
  test:
    runs-on: ubuntu-latest
    strategy:
      matrix:
        environment: [development, staging]

    steps:
    - uses: actions/checkout@v2

    - name: Setup Node.js
      uses: actions/setup-node@v2
      with:
        node-version: '16'

    - name: Install Newman
      run: npm install -g newman newman-reporter-html newman-reporter-junitfull

    - name: Set environment variables
      run: |
        echo "BASE_URL=${{ secrets[format('{0}_BASE_URL', matrix.environment)] }}" >> $GITHUB_ENV
        echo "API_KEY=${{ secrets[format('{0}_API_KEY', matrix.environment)] }}" >> $GITHUB_ENV

    - name: Run API Tests
      id: newman
      continue-on-error: true
      run: |
        newman run tests/UserAPI.postman_collection.json \
          -e environments/${{ matrix.environment }}.postman_environment.json \
          -d data/test-data.csv \
          -n 3 \
          --delay-request 1000 \
          --timeout-request 10000 \
          --reporters cli,json,junit,html \
          --reporter-json-export reports/results-${{ matrix.environment }}.json \
          --reporter-junit-export reports/junit-${{ matrix.environment }}.xml \
          --reporter-html-export reports/report-${{ matrix.environment }}.html

    - name: Upload Test Reports
      uses: actions/upload-artifact@v2
      if: always()
      with:
        name: test-reports-${{ matrix.environment }}
        path: reports/

    - name: Publish Test Results
      uses: EnricoMi/publish-unit-test-result-action@v1
