**4. Advanced Newman with Custom Reporters**

```javascript
// custom-reporter.js
module.exports = function(emitter, reporterOptions, collectionRunOptions) {
    const results = {
        startTime: new Date(),
        iterations: 0,
        assertions: {
            total: 0,
            passed: 0,
            failed: 0
        },
        requests: []
    };

    emitter.on('start', function(err, args) {
        console.log('Test run started');
    });

    emitter.on('beforeItem', function(err, args) {
        results.iterations++;
    });

    emitter.on('assertion', function(err, args) {
        results.assertions.total++;
        if (args.assertion.passed) {
            results.assertions.passed++;
        } else {
            results.assertions.failed++;
            results.requests.push({
                name: args.item.name,
                error: args.assertion.error.message
            });
        }
    });

    emitter.on('done', function(err, args) {
        results.endTime = new Date();
        results.duration = results.endTime - results.startTime;

        // Generate custom report
        const report = `
        ====================
        API Test Report
        ====================
        Start: ${results.startTime}
        End: ${results.endTime}
        Duration: ${results.duration}ms
        Iterations: ${results.iterations}

        Assertions:
        Total: ${results.assertions.total}
        Passed: ${results.assertions.passed}
        Failed: ${results.assertions.failed}
        Pass Rate: ${(results.assertions.passed/results.assertions.total*100).toFixed(2)}%

        Failures:
        ${results.requests.map(r => `- ${r.name}: ${r.error}`).join('\n')}
        `;

        console.log(report);
        require('fs').writeFileSync('custom-report.txt', report);
    });
};
