// JWT token security
pm.test('JWT token is properly secured', () => {
    const token = pm.response.json().token;
    if (token) {
        // Check token structure
        const parts = token.split('.');
        pm.expect(parts.length).to.equal(3);

        // Decode header and payload (without verification)
        const header = JSON.parse(atob(parts[0]));
        const payload = JSON.parse(atob(parts[1]));

        // Check algorithm (should be RS256, not none)
        pm.expect(header.alg).to.not.equal('none');
        pm.expect(['HS256', 'RS256']).to.include(header.alg);

        // Check expiration
        pm.expect(payload.exp).to.be.above(Math.floor(Date.now() / 1000));
    }
});

// Rate limiting test
pm.test('Rate limiting headers present and valid', () => {
    const headers = pm.response.headers;

    // Check standard rate limit headers
