**2. Reusable Utility Functions**

```javascript
// Define utility functions in collection pre-request script

const Utils = {
    // Generate unique email
    uniqueEmail: function(prefix = 'test') {
        return `${prefix}${Date.now()}@example.com`;
    },

    // Format date for API
    formatDate: function(date = new Date()) {
        return date.toISOString();
    },

    // Mask sensitive data for logs
    maskValue: function(value, visibleChars = 4) {
        if (!value) return value;
        if (value.length <= visibleChars) return '*'.repeat(value.length);
        return value.substring(0, visibleChars) + '...' + value.substring(value.length - visibleChars);
    },

    // Wait for condition (async)
    waitFor: async function(condition, timeout = 5000, interval = 500) {
        const start = Date.now();
        while (Date.now() - start < timeout) {
            if (await condition()) return true;
            await new Promise(resolve => setTimeout(resolve, interval));
        }
        return false;
    },

    // Parse response safely
    safeParse: function(response) {
        try {
            return typeof response === 'string' ? JSON.parse(response) : response;
        } catch (e) {
            console.error('Failed to parse response:', e);
            return null;
        }
    },

    // Generate test data
    generateUser: function() {
        const timestamp = Date.now();
        return {
            name: `Test User ${timestamp}`,
            email: `user${timestamp}@example.com`,
            password: 'Test@123456',
            role: ['admin', 'user', 'guest'][Math.floor(Math.random() * 3)]
        };
    }
};

// Make available globally
pm.variables.set('Utils', Utils);
