```javascript
// Common test patterns as functions

const TestHelpers = {
    // Test status code
    expectStatus: function(expectedCode) {
        pm.test(`Status code is ${expectedCode}`, () => {
            pm.expect(pm.response.code).to.equal(expectedCode);
        });
    },

    // Test response time
    expectResponseTime: function(maxTime = 500) {
        pm.test(`Response time < ${maxTime}ms`, () => {
            pm.expect(pm.response.responseTime).to.be.below(maxTime);
        });
    },

    // Test required fields
    expectFields: function(fields) {
        const response = pm.response.json();
        fields.forEach(field => {
            pm.test(`Response has field: ${field}`, () => {
                pm.expect(response).to.have.property(field);
            });
        });
    },

    // Test field types
    expectFieldType: function(field, type) {
        pm.test(`Field ${field} is type ${type}`, () => {
            const response = pm.response.json();
            pm.expect(response[field]).to.be.a(type);
        });
    },

    // Test array not empty
    expectArrayNotEmpty: function(arrayPath) {
        pm.test('Array is not empty', () => {
            const response = pm.response.json();
            const arr = arrayPath.split('.').reduce((obj, key) => obj[key], response);
            pm.expect(arr).to.be.an('array').that.is.not.empty;
        });
    },

    // Test header exists
    expectHeader: function(headerName) {
        pm.test(`Header ${headerName} exists`, () => {
            pm.response.to.have.header(headerName);
        });
    }
};

