const CONFIG = {
    timeout: pm.collectionVariables.get('timeout'),
    retryCount: pm.collectionVariables.get('retryCount')
};

// 2. Utility functions
function generateRequestId() {
    return pm.variables.replaceIn('{{$guid}}');
}

function getAuthHeader() {
