    return token ? `Bearer ${token}` : null;
}

// 3. Main logic
(function() {
    console.log(`Starting: ${pm.request.name}`);

    // Add request ID
    pm.request.headers.add({
        key: 'X-Request-ID',
        value: generateRequestId()
    });

    // Add auth if needed
    const authHeader = getAuthHeader();
    if (authHeader && !pm.request.url.includes('/login')) {
        pm.request.headers.add({
            key: 'Authorization',
            value: authHeader
        });
    }

    // Generate test data if needed
    if (pm.request.method === 'POST' && pm.request.url.includes('/users')) {
        const testUser = DataGenerator.user();
        pm.request.body.raw = JSON.stringify(testUser);
        pm.variables.set('testEmail', testUser.email);
    }
})();

