**6. Secure Data in Logs**

```javascript
// Safe logging practices

// Custom safe logger
const SafeLogger = {
    sensitiveKeys: ['password', 'token', 'secret', 'key', 'authorization'],

    log: function(message, data = null) {
        if (!data) {
            console.log(message);
            return;
        }

        // Create safe copy
        const safeData = JSON.parse(JSON.stringify(data));

        // Mask sensitive values
        this.maskSensitiveData(safeData);

        console.log(message, JSON.stringify(safeData, null, 2));
    },

    maskSensitiveData: function(obj) {
        if (!obj || typeof obj !== 'object') return;

        Object.keys(obj).forEach(key => {
            if (this.sensitiveKeys.includes(key.toLowerCase())) {
                obj[key] = '***MASKED***';
            } else if (typeof obj[key] === 'object') {
                this.maskSensitiveData(obj[key]);
            }
        });
    },

    logRequest: function() {
        const safeRequest = {
            method: pm.request.method,
            url: pm.request.url.toString(),
            headers: {}
        };

        // Safe headers
        pm.request.headers.each(header => {
            if (this.sensitiveKeys.includes(header.key.toLowerCase())) {
                safeRequest.headers[header.key] = '***MASKED***';
            } else {
                safeRequest.headers[header.key] = header.value;
            }
        });

        console.log('Request:', JSON.stringify(safeRequest, null, 2));
    }
};

// Usage
SafeLogger.logRequest();
SafeLogger.log('Response received', pm.response.json());
