    key: 'X-Test-ID',
    value: `test-${testConfig.timestamp}`
});

pm.request.headers.add({
    key: 'X-Environment',
    value: testConfig.environment
});

// 4. Log test start
console.log(`[${new Date().toISOString()}] Starting test: ${pm.info.requestName}`);
console.log(`Test data:`, testData);

// Tests Script
// ============================================
// 1. Basic response validation
