    pm.response.to.have.status(201);
});

pm.test('Response time is acceptable', () => {
    const timeout = pm.environment.get('timeout') || 1000;
    pm.expect(pm.response.responseTime).to.be.below(timeout);
});

pm.test('Response has valid JSON', () => {
    pm.response.to.have.jsonBody();
});

// 2. Parse response
const response = pm.response.json();

// 3. Validate response structure
pm.test('Response has required fields', () => {
    const required = ['id', 'email', 'name', 'createdAt'];
    required.forEach(field => {
        pm.expect(response).to.have.property(field);
    });
});

// 4. Validate data types
pm.test('Data types are correct', () => {
    pm.expect(response.id).to.be.a('number');
    pm.expect(response.email).to.be.a('string');
    pm.expect(response.name).to.be.a('string');
    pm.expect(response.createdAt).to.match(/^\d{4}-\d{2}-\d{2}T/);
});

// 5. Business logic validation
pm.test('Created user matches request data', () => {
    const requestData = JSON.parse(pm.request.body.raw);
    pm.expect(response.email).to.equal(requestData.email);
    pm.expect(response.name).to.equal(requestData.name);
});

// 6. Save data for subsequent tests
pm.environment.set('createdUserId', response.id);
console.log(`✅ Created user with ID: ${response.id}`);

// 7. Performance tracking
const responseTime = pm.response.responseTime;
if (responseTime > 800) {
    console.warn(`⚠️ Slow response: ${responseTime}ms`);
