**3. Custom Report Generation**

```javascript
// custom-reporter.js
const fs = require('fs');
const path = require('path');

class CustomReporter {
    constructor(emitter, reporterOptions, collectionRunOptions) {
        this.results = {
            summary: {
                startTime: new Date(),
                endTime: null,
                totalTests: 0,
                passed: 0,
                failed: 0,
                skipped: 0,
                totalTime: 0
            },
            failures: [],
            performance: [],
            requests: []
        };

        emitter.on('start', this.handleStart.bind(this));
        emitter.on('assertion', this.handleAssertion.bind(this));
        emitter.on('request', this.handleRequest.bind(this));
        emitter.on('done', this.handleDone.bind(this));
    }

    handleStart(err, args) {
        console.log('Test run started');
    }

    handleAssertion(err, args) {
        this.results.summary.totalTests++;

        if (args.assertion.passed) {
            this.results.summary.passed++;
        } else {
            this.results.summary.failed++;
            this.results.failures.push({
                test: args.assertion.test,
                error: args.assertion.error.message,
                request: args.item.name,
                iteration: args.cursor.iteration
            });
        }
    }

    handleRequest(err, args) {
        this.results.requests.push({
            name: args.item.name,
            method: args.request.method,
            url: args.request.url.toString(),
            status: args.response ? args.response.code : 'Error',
            time: args.response ? args.response.responseTime : 0,
            size: args.response ? args.response.responseSize : 0
        });

        // Track performance
        if (args.response && args.response.responseTime > 1000) {
            this.results.performance.push({
                request: args.item.name,
                time: args.response.responseTime,
                threshold: 1000
            });
        }
    }

    handleDone(err, args) {
        this.results.summary.endTime = new Date();
        this.results.summary.totalTime = this.results.summary.endTime - this.results.summary.startTime;

        // Generate custom report
        this.generateReport();
    }

    generateReport() {
        const report = `
        ╔══════════════════════════════════════════╗
        ║         CUSTOM TEST REPORT               ║
        ╚══════════════════════════════════════════╝

        📅 Start Time: ${this.results.summary.startTime}
        📅 End Time: ${this.results.summary.endTime}
        ⏱️  Duration: ${this.results.summary.totalTime}ms

        📊 SUMMARY
        ──────────────────────────────────────────
        Total Tests: ${this.results.summary.totalTests}
        ✅ Passed: ${this.results.summary.passed}
        ❌ Failed: ${this.results.summary.failed}
        ⏭️  Skipped: ${this.results.summary.skipped}
        📈 Pass Rate: ${((this.results.summary.passed / this.results.summary.totalTests) * 100).toFixed(2)}%

        ${this.results.failures.length > 0 ? '❌ FAILURES' : '✅ NO FAILURES'}
        ──────────────────────────────────────────
        ${this.results.failures.map(f => 
            `- ${f.test}: ${f.error} (${f.request})`
        ).join('\n')}

        ⚠️ SLOW REQUESTS (>1000ms)
        ──────────────────────────────────────────
        ${this.results.performance.map(p => 
            `- ${p.request}: ${p.time}ms`
        ).join('\n')}
        `;

        fs.writeFileSync('custom-report.txt', report);
        console.log('📄 Custom report generated: custom-report.txt');
    }
}

module.exports = CustomReporter;
```

