```javascript
// parse-results.js
const fs = require('fs');

// Read Newman JSON results
const results = JSON.parse(fs.readFileSync('reports/results.json', 'utf8'));

// Extract metrics
const metrics = {
    totalTests: results.run.stats.tests.total,
    passedTests: results.run.stats.tests.passed,
    failedTests: results.run.stats.tests.failed,
    pendingTests: results.run.stats.tests.pending,
    totalTime: results.run.timings.completed - results.run.timings.started,

    requests: results.run.executions.map(exec => ({
        name: exec.item.name,
        method: exec.request.method,
        url: exec.request.url,
        status: exec.response ? exec.response.code : 'Error',
        time: exec.response ? exec.response.responseTime : 0,
        size: exec.response ? exec.response.responseSize : 0
    })),

    failures: results.run.failures.map(f => ({
        test: f.error.test,
        message: f.error.message,
        request: f.source.name
    }))
};

// Calculate pass rate
metrics.passRate = (metrics.passedTests / metrics.totalTests * 100).toFixed(2);

// Find slow tests
metrics.slowTests = metrics.requests
    .filter(r => r.time > 1000)
    .sort((a, b) => b.time - a.time);

// Generate summary
console.log('\n📊 METRICS SUMMARY');
console.log('══════════════════════════════');
console.log(`Total Tests: ${metrics.totalTests}`);
console.log(`✅ Passed: ${metrics.passedTests}`);
console.log(`❌ Failed: ${metrics.failedTests}`);
console.log(`📈 Pass Rate: ${metrics.passRate}%`);
console.log(`⏱️  Total Time: ${metrics.totalTime}ms`);

if (metrics.slowTests.length > 0) {
    console.log('\n⚠️  SLOW TESTS (>1000ms)');
    metrics.slowTests.forEach(t => {
        console.log(`  ${t.name}: ${t.time}ms`);
    });
}

// Export for CI/CD
fs.writeFileSync('reports/metrics.json', JSON.stringify(metrics, null, 2));
