if (rawPassword != null && !rawPassword.startsWith("HASHED_")) {
    MessageDigest md = MessageDigest.getInstance("SHA-256");
    byte[] hash = md.digest(rawPassword.getBytes("UTF-8"));
    String hashed = DatatypeConverter.printHexBinary(hash);
    vars.put("securePassword", "HASHED_" + hashed.substring(0, 16));
}

// Mask email addresses
String email = vars.get("email");
if (email != null && email.contains("@")) {
    String[] parts = email.split("@");
    String masked = parts[0].substring(0, 2) + "****@" + parts[1];
    vars.put("maskedEmail", masked);
}
