```java
// CustomFunction.java - Compile and place in JMeter classpath
package com.test.functions;

import org.apache.jmeter.engine.util.CompoundVariable;
import org.apache.jmeter.functions.AbstractFunction;
import org.apache.jmeter.functions.InvalidParameterException;
import org.apache.jmeter.samplers.SampleResult;
import org.apache.jmeter.samplers.Sampler;

import java.util.Collection;
import java.util.LinkedList;
import java.util.List;
import java.util.UUID;

public class GenerateUUID extends AbstractFunction {

    private static final List<String> DESC = new LinkedList<>();
    private static final String KEY = "__generateUUID";

    static {
        DESC.add("Generate a random UUID");
    }

    private CompoundVariable[] values;

    @Override
    public String execute(SampleResult previousResult, Sampler currentSampler)
            throws InvalidParameterException {
        return UUID.randomUUID().toString();
    }

    @Override
    public void setParameters(Collection<CompoundVariable> parameters)
            throws InvalidParameterException {
        values = parameters.toArray(new CompoundVariable[parameters.size()]);
    }

    @Override
    public String getReferenceKey() {
        return KEY;
    }

    @Override
    public List<String> getArgumentDesc() {
        return DESC;
    }
}
