**Version-Controlled, Repeatable, and Maintainable:**

Pipeline as Code puts your performance test automation in version control alongside your application code. This enables review, iteration, and consistency.

**1. Basic Declarative Pipeline**

```groovy
// Jenkinsfile
pipeline {
    agent any

    parameters {
        string(name: 'USERS', defaultValue: '100', description: 'Number of virtual users')
        choice(name: 'ENVIRONMENT', choices: ['dev', 'staging', 'prod'], description: 'Target environment')
        string(name: 'DURATION', defaultValue: '300', description: 'Test duration in seconds')
    }

    environment {
        JMETER_HOME = '/opt/jmeter'
        RESULTS_DIR = 'results'
        REPORT_DIR = 'report'
    }

    stages {
        stage('Checkout') {
            steps {
                checkout scm
            }
        }

        stage('Setup') {
            steps {
                sh '''
                    mkdir -p ${RESULTS_DIR} ${REPORT_DIR}
                    echo "Starting performance test at $(date)"
                    echo "Environment: ${ENVIRONMENT}"
                    echo "Users: ${USERS}"
                    echo "Duration: ${DURATION}s"
                '''
            }
        }

        stage('Run JMeter Test') {
            steps {
                sh '''
                    ${JMETER_HOME}/bin/jmeter -n \
                        -t api_load_test.jmx \
                        -l ${RESULTS_DIR}/results.jtl \
                        -j ${RESULTS_DIR}/jmeter.log \
                        -Jusers=${USERS} \
                        -Jrampup=${params.RAMPUP ?: 60} \
                        -Jduration=${DURATION} \
                        -Jenvironment=${ENVIRONMENT} \
                        -X
                '''
            }
            post {
                failure {
                    echo 'JMeter test execution failed!'
                    unstable('Test execution failed')
                }
            }
        }

        stage('Generate Report') {
            steps {
                sh '''
                    ${JMETER_HOME}/bin/jmeter -g ${RESULTS_DIR}/results.jtl \
                        -o ${REPORT_DIR} \
                        -Jjmeter.reportgenerator.title="Performance Test: ${ENVIRONMENT} - ${BUILD_NUMBER}"
                '''
            }
        }

        stage('Analyze Results') {
            steps {
                script {
                    // Parse results and set build status
                    def results = readFile('results/results.jtl')
                    def errorRate = calculateErrorRate(results)
                    def avgResponseTime = calculateAvgResponseTime(results)

                    echo "Error Rate: ${errorRate}%"
                    echo "Avg Response Time: ${avgResponseTime}ms"

                    // Thresholds
                    if (errorRate > 5.0) {
                        error "Error rate ${errorRate}% exceeds threshold 5%"
                    } else if (errorRate > 1.0) {
                        unstable("Error rate ${errorRate}% exceeds warning threshold 1%")
                    }

                    if (avgResponseTime > 2000) {
                        unstable("Avg response time ${avgResponseTime}ms exceeds threshold 2000ms")
                    }
                }
            }
        }
    }

    post {
        always {
            // Publish reports
            publishHTML([
                reportDir: REPORT_DIR,
                reportFiles: 'index.html',
                reportName: 'Performance Report'
            ])

            // Archive artifacts
            archiveArtifacts artifacts: "${RESULTS_DIR}/*, ${REPORT_DIR}/**/*", fingerprint: true

            // Clean up
            cleanWs()
        }

        success {
            echo 'Performance test completed successfully'
            // Trigger next stage or send notification
        }

        failure {
            emailext(
                to: 'team@company.com',
                subject: "Performance Test Failed: ${env.JOB_NAME} - ${env.BUILD_NUMBER}",
                body: "Check console output at ${env.BUILD_URL}"
            )
        }
    }
}

// Helper functions
def calculateErrorRate(String results) {
    // Parse JTL and calculate error percentage
    def lines = results.split('\n')
    def total = lines.size() - 1  // Skip header
    def errors = lines.findAll { it.contains(',true,') ? false : true }.size() - 1
    return total > 0 ? (errors * 100.0 / total) : 0
}

def calculateAvgResponseTime(String results) {
    // Parse JTL and calculate average response time
    def lines = results.split('\n')
    def times = []
    lines.eachWithIndex { line, index ->
        if (index > 0 && line.contains(',')) {
            def parts = line.split(',')
            if (parts.size() > 1) {
                times << parts[1].toInteger()
            }
        }
    }
    return times.size() > 0 ? times.sum() / times.size() : 0
}
```

