                    // Combine results from parallel runs
                    sh '''
                        mkdir -p aggregate_results
                        cat api_results/results.jtl > aggregate_results/combined.jtl
                        tail -n +2 web_results/results.jtl >> aggregate_results/combined.jtl
                        tail -n +2 db_results/results.jtl >> aggregate_results/combined.jtl

                        /opt/jmeter/bin/jmeter -g aggregate_results/combined.jtl \
                            -o aggregate_report
                    '''
                }
            }
        }
    }
}

def runJmeterTest(String testPlan, String resultDir, String testName) {
