**5. Performance Gates and Quality Checks**

```groovy
pipeline {
    agent any

    environment {
        // Baseline values from previous successful run
        BASELINE_RESPONSE_TIME = '1500'
        BASELINE_ERROR_RATE = '0.5'
        BASELINE_THROUGHPUT = '100'
    }

    stages {
        stage('Performance Test') {
            steps {
                script {
                    // Run test and capture metrics
                    sh '''
                        /opt/jmeter/bin/jmeter -n -t test.jmx -l results.jtl
                        /opt/jmeter/bin/jmeter -g results.jtl -o report
                    '''

                    def metrics = parseMetrics('results.jtl')

                    // Compare with baseline
                    def degradationChecks = [
                        responseTime: checkDegradation(
                            current: metrics.avgResponseTime,
                            baseline: BASELINE_RESPONSE_TIME.toInteger(),
                            threshold: 20 // 20% degradation allowed
                        ),
                        errorRate: checkDegradation(
                            current: metrics.errorRate,
                            baseline: BASELINE_ERROR_RATE.toDouble(),
                            threshold: 50 // 50% increase allowed
                        ),
                        throughput: checkDegradation(
                            current: metrics.throughput,
                            baseline: BASELINE_THROUGHPUT.toInteger(),
                            threshold: 15, // 15% decrease allowed
                            higherIsBetter: true
                        )
                    ]

                    // Apply quality gates
                    def failedGates = degradationChecks.findAll { !it.value.passed }

                    if (failedGates) {
                        echo "Performance gates failed:"
                        failedGates.each { gate, result ->
                            echo "- ${gate}: ${result.message}"
                        }

                        if (degradationChecks.responseTime.degradation > 30) {
                            error "Critical performance degradation detected"
                        } else {
                            unstable "Performance degradation detected"
                        }
                    }

                    // Update baseline if current run is successful
                    if (currentBuild.result == 'SUCCESS') {
                        updateBaseline(metrics)
                    }
                }
            }
        }
    }
}

def checkDegradation(Map args) {
    def current = args.current
    def baseline = args.baseline
    def threshold = args.threshold
    def higherIsBetter = args.higherIsBetter ?: false

    def change = ((current - baseline) / baseline) * 100
    def passed = higherIsBetter ? change >= -threshold : change <= threshold

    def direction = higherIsBetter ? 'increase' : 'decrease'
    def message = "${direction} of ${Math.abs(change).round(1)}% (threshold: ${threshold}%)"

    return [passed: passed, degradation: change, message: message]
}

def parseMetrics(String jtlFile) {
    def lines = readFile(jtlFile).split('\n')
    def totalTime = 0
    def totalSamples = 0
    def errors = 0
    def startTime = null
    def endTime = null

    lines.eachWithIndex { line, idx ->
        if (idx > 0 && line.contains(',')) {
            def parts = line.split(',')
            totalTime += parts[1].toInteger()
            totalSamples++

            if (parts[7] == 'false') { // success flag
                errors++
            }

            def timestamp = parts[0].toLong()
            if (startTime == null || timestamp < startTime) startTime = timestamp
            if (endTime == null || timestamp > endTime) endTime = timestamp
        }
    }

    def durationSec = (endTime - startTime) / 1000

    return [
        avgResponseTime: totalSamples > 0 ? totalTime / totalSamples : 0,
        errorRate: totalSamples > 0 ? (errors * 100.0 / totalSamples) : 0,
        throughput: durationSec > 0 ? totalSamples / durationSec : 0,
        totalSamples: totalSamples,
        errors: errors
    ]
}

def updateBaseline(metrics) {
    // Store in Jenkins environment or external database
    echo "Updating baseline with new metrics: ${metrics}"
    // Implementation depends on your storage strategy
}
