**4. Performance Regression Detection**

```groovy
// Advanced regression detection using statistical methods
stage('Regression Detection') {
    steps {
        script {
            // Get historical data from previous builds
            def historicalData = getHistoricalPerformance()
            def currentData = parseJTL('results.jtl')

            // Calculate statistics
            def stats = calculateStatistics(historicalData)

            // Check for anomalies
            def anomalies = []

            if (currentData.avgResponseTime > stats.meanResponseTime + 2 * stats.stdDevResponseTime) {
                anomalies.add("Response time ${currentData.avgResponseTime}ms exceeds 2 sigma threshold (${stats.meanResponseTime + 2 * stats.stdDevResponseTime}ms)")
            }

            if (currentData.errorRate > stats.meanErrorRate + 3 * stats.stdDevErrorRate) {
                anomalies.add("Error rate ${currentData.errorRate}% exceeds 3 sigma threshold (${stats.meanErrorRate + 3 * stats.stdDevErrorRate}%)")
            }

            if (anomalies) {
                echo "Anomalies detected:"
                anomalies.each { echo "- ${it}" }

                if (anomalies.size() >= 2) {
                    unstable("Multiple performance anomalies detected")
                }
            }
        }
    }
}

def getHistoricalPerformance() {
    def data = []
    def job = Jenkins.instance.getItemByFullName(env.JOB_NAME)

    // Get last 20 successful builds
    job.builds.findAll { it.result == 'SUCCESS' }.take(20).each { build ->
        def report = build.artifacts.find { it.fileName == 'results.jtl' }
        if (report) {
            // Parse the JTL from the build
            data << parseJTLFromBuild(build)
        }
    }

    return data
}

def calculateStatistics(List data) {
    def responseTimes = data.collect { it.avgResponseTime }
    def errorRates = data.collect { it.errorRate }

    return [
        meanResponseTime: mean(responseTimes),
        stdDevResponseTime: stdDev(responseTimes),
        meanErrorRate: mean(errorRates),
        stdDevErrorRate: stdDev(errorRates)
    ]
}
