**5. Error Handling**

```c
// Check response code
int rc = web_get_int_property(HTTP_INFO_RETURN_CODE);
if (rc != 200 && rc != 302) {
    lr_error_message("Unexpected response code: %d", rc);
    lr_end_transaction("Login", LR_FAIL);
    return -1;
}

// Retry on failure
int maxRetries = 3;
int retryCount = 0;
int success = 0;

while (!success && retryCount < maxRetries) {
    retryCount++;
    lr_output_message("Attempt %d of %d", retryCount, maxRetries);

    web_url("search", ...);

    if (web_get_int_property(HTTP_INFO_RETURN_CODE) == 200) {
        success = 1;
    } else {
        lr_think_time(2);  // Wait before retry
    }
}

if (!success) {
    lr_error_message("Failed after %d retries", maxRetries);
}

// Graceful degradation
if (web_get_int_property(HTTP_INFO_RETURN_CODE) == 503) {
    lr_output_message("Service unavailable, skipping checkout");
    lr_end_transaction("Checkout", LR_STOP);
    return 0;  // Continue with next iteration
}
```

