**The Scenario:** An airline booking website. The process is: (1) Search for flights, (2) A list of available flights is returned, (3) User clicks on a specific flight, (4) A seat map is displayed, (5) User selects a preferred seat type (if available).

**The Advanced Scripting Solution:**

```c
Action()
{
    int num_flights, i;
    char flight_id_param[50];
    int seat_selected = 0;

    lr_start_transaction("Flight_Search_and_Select");

    // Step 1: Search for flights (standard recorded steps)
    web_submit_data("flight_search.php",
        "Action=https://example.com/flights/search",
        "Method=POST",
        ITEMDATA,
        "Name=origin", "Value=LAX", ENDITEM,
        "Name=dest", "Value=JFK", ENDITEM,
        "Name=date", "Value=2024-05-20", ENDITEM,
        LAST);

    // Step 2: Capture all available flight IDs from the search results
    web_reg_save_param("flight_id",
        "LB=<input type=\"radio\" name=\"flight\" value=\"",
        "RB=\">",
        "Ord=All",
        "Search=Body",
        LAST);

    web_url("flight_results.php",
        "URL=https://example.com/flights/results",
        ...
        LAST);

    num_flights = atoi(lr_eval_string("{flight_id_count}"));
    lr_output_message("Found %d flights.", num_flights);

    if (num_flights == 0) {
        lr_error_message("No flights found. Aborting.");
        lr_end_transaction("Flight_Search_and_Select", LR_FAIL);
        return -1;
    }

    // Step 3: Loop through flights until we find one with a preferred aisle seat
    for (i = 1; i <= num_flights; i++) {
        sprintf(flight_id_param, "{flight_id_%d}", i);
        lr_save_string(lr_eval_string(flight_id_param), "SelectedFlight");
        lr_output_message("Trying flight: %s", lr_eval_string("{SelectedFlight}"));

        // Step 4: Click on the flight to see seat map
        web_submit_data("select_flight.php",
            "Action=https://example.com/flights/select",
            "Method=POST",
            ITEMDATA,
            "Name=flight", "Value={SelectedFlight}", ENDITEM,
            LAST);

        // Step 5: Check if an aisle seat (seat type 'A') is available
        web_reg_save_param("aisle_seat",
            "LB=seatType=\"A\" seatId=\"",
            "RB=\"",
            "Ord=1", // Just need to know if at least one exists
            LAST);

        web_url("seat_map.php",
            "URL=https://example.com/flights/seatmap?flight={SelectedFlight}",
            ...
            LAST);

        if (strlen(lr_eval_string("{aisle_seat}")) > 0) {
            lr_output_message("Aisle seat found on flight %s!", lr_eval_string("{SelectedFlight}"));
            seat_selected = 1;
            break; // Exit the loop, we have our flight
        } else {
            lr_output_message("No aisle seat on this flight. Trying next.");
        }
    }

    // Step 6: Outcome of the search
    if (seat_selected == 1) {
        // Proceed to book the seat
        web_submit_data("book_seat.php",
            "Action=https://example.com/flights/book",
            "Method=POST",
            ITEMDATA,
            "Name=flight", "Value={SelectedFlight}", ENDITEM,
            "Name=seatId", "Value={aisle_seat}", ENDITEM,
            LAST);
        lr_end_transaction("Flight_Search_and_Select", LR_PASS);
    } else {
        lr_error_message("Could not find a flight with an aisle seat.");
        lr_end_transaction("Flight_Search_and_Select", LR_FAIL);
    }

    return 0;
}
```

