```groovy
plugins {
    id 'java'
    id 'application'
    id 'idea'
    id 'eclipse'
}

repositories {
    mavenCentral()
}

dependencies {
    // TestNG
    testImplementation 'org.testng:testng:7.8.0'

    // Selenium for web testing
    testImplementation 'org.seleniumhq.selenium:selenium-java:4.12.0'

    // WebDriverManager for automatic driver management
    testImplementation 'io.github.bonigarcia:webdrivermanager:5.5.3'

    // Logging
    testImplementation 'org.slf4j:slf4j-simple:2.0.9'

    // JSON handling
    testImplementation 'com.google.code.gson:gson:2.10.1'

    // Apache Commons for utilities
    testImplementation 'org.apache.commons:commons-lang3:3.13.0'
}

// Configure Java version
java {
    sourceCompatibility = JavaVersion.VERSION_11
    targetCompatibility = JavaVersion.VERSION_11
}

// Configure test task
test {
    useTestNG() {
        // Parallel execution configuration
        parallel = System.getProperty('test.parallel', 'methods')
        threadCount = System.getProperty('test.threadCount', '4') as int

        // Test suite configuration
        if (file('testng.xml').exists()) {
            suites 'testng.xml'
        }

        // Test groups from system properties
        if (System.getProperty('include.groups')) {
            includeGroups System.getProperty('include.groups').split(',')
        }
        if (System.getProperty('exclude.groups')) {
            excludeGroups System.getProperty('exclude.groups').split(',')
        }

        // Output directory for TestNG reports
        outputDirectory = file("${buildDir}/reports/testng")
    }

    // System properties for tests
    systemProperties = [
        'browser': System.getProperty('browser', 'chrome'),
        'environment': System.getProperty('environment', 'staging'),
        'headless': System.getProperty('headless', 'true'),
        'baseUrl': System.getProperty('baseUrl', 'https://example.com'),
        'buildNumber': System.getProperty('buildNumber', 'local'),
        'timestamp': new Date().format('yyyy-MM-dd HH:mm:ss')
    ]

    // Test logging configuration
    testLogging {
        // Show test events
        events "PASSED", "FAILED", "SKIPPED", "STANDARD_OUT", "STANDARD_ERROR"

        // Show exception details
        exceptionFormat = 'full'

        // Show standard streams
        showStandardStreams = true

        // Show stack traces
        showStackTraces = true

        // Show test summaries
        afterSuite { desc, result ->
            if (!desc.parent) {
                println "\nTest Results: ${result.resultType}"
                println "Tests run: ${result.testCount}, " +
                    "Failures: ${result.failedTestCount}, " +
                    "Skipped: ${result.skippedTestCount}"
            }
        }
    }

    // Fail the build on test failures
    ignoreFailures = false

    // Maximum parallel forks
    maxParallelForks = Runtime.runtime.availableProcessors()

    // Test reports directory
    reportsDir = file("${buildDir}/custom-reports")

    // Enable assertions
    enableAssertions = true
}

// Task to run smoke tests
task smokeTest(type: Test) {
    useTestNG() {
        includeGroups 'smoke'
        parallel = 'methods'
        threadCount = 2
    }

    systemProperties = System.properties
    testLogging.events = ["PASSED", "FAILED", "SKIPPED"]
}

// Task to run regression tests
task regressionTest(type: Test) {
    useTestNG() {
        includeGroups 'regression'
        excludeGroups 'broken', 'flaky'
        parallel = 'classes'
        threadCount = 4
    }

    systemProperties = System.properties
    testLogging.events = ["PASSED", "FAILED", "SKIPPED"]
}

// Task to run cross-browser tests
task crossBrowserTest(type: Test) {
    useTestNG() {
        includeGroups 'cross-browser'
        parallel = 'methods'
        threadCount = 3
    }

    systemProperties = System.properties
    testLogging.events = ["PASSED", "FAILED", "SKIPPED"]
}

// Task to generate test report only
task testReport(type: TestReport) {
    destinationDir = file("${buildDir}/reports/all-tests")
    reportOn test.binaryResultsDirectory
}

// Task to clean old reports
task cleanReports(type: Delete) {
    delete file("${buildDir}/reports")
    delete file("${buildDir}/test-results")
}

// Ensure clean reports before test
clean.dependsOn cleanReports

// Configure application
application {
    mainClass = 'com.example.App'
}

// IDE configuration
tasks.withType(JavaCompile) {
    options.encoding = 'UTF-8'
    options.compilerArgs << '-Xlint:unchecked' << '-Xlint:deprecation'
}
