    @BeforeMethod
    public void beforeMethod() {
        System.out.println("4. @BeforeMethod");
    }

    @Test
    public void test1() {
        System.out.println("5. @Test 1");
        Assert.assertTrue(true);
    }

    @Test
    public void test2() {
        System.out.println("5. @Test 2");
        Assert.assertTrue(true);
    }

    @AfterMethod
    public void afterMethod() {
        System.out.println("6. @AfterMethod");
    }

    @AfterClass
    public void afterClass() {
        System.out.println("7. @AfterClass");
    }

    @AfterTest
    public void afterTest() {
        System.out.println("8. @AfterTest");
    }

    @AfterSuite
    public void afterSuite() {
        System.out.println("9. @AfterSuite");
    }
}
```
Run the test and check console output for correct order.

Create `ParameterTest.java`:
```java
