**Example: Well-Structured Test Class**

```java
package com.example.tests.authentication;

import org.testng.annotations.*;
import org.testng.Assert;
import com.example.pages.LoginPage;
import com.example.models.User;
import com.example.utils.TestDataFactory;

/**
 * Test class for login functionality.
 * Covers positive and negative scenarios for user authentication.
 */
public class LoginTest extends BaseTest {

    private LoginPage loginPage;
    private User validUser;

    @BeforeClass
    public void classSetup() {
        // Initialize page objects
        loginPage = new LoginPage(driver);

        // Load test data
        validUser = TestDataFactory.getValidUser();
    }

    @BeforeMethod
    public void methodSetup() {
        // Navigate to login page before each test
        loginPage.navigateTo();
    }

    // ==================== POSITIVE TESTS ====================

    @Test(description = "Should login successfully with valid credentials")
    public void shouldLoginWithValidCredentials() {
        boolean result = loginPage.login(
            validUser.getEmail(), 
            validUser.getPassword()
        );

        Assert.assertTrue(result, "Login should succeed");
        Assert.assertTrue(loginPage.isLoggedIn(), "User should be logged in");
        Assert.assertEquals(loginPage.getWelcomeMessage(), 
            "Welcome, " + validUser.getName());
    }

    @Test(description = "Should remember user when 'Remember Me' is checked")
    public void shouldRememberUser() {
        loginPage.checkRememberMe();
        loginPage.login(validUser.getEmail(), validUser.getPassword());

        // Verify cookie is set
        Assert.assertTrue(loginPage.hasRememberMeCookie());
    }

    // ==================== NEGATIVE TESTS ====================

    @Test(description = "Should fail login with invalid password")
    public void shouldFailWithInvalidPassword() {
        boolean result = loginPage.login(
            validUser.getEmail(), 
            "wrongpassword"
        );

        Assert.assertFalse(result, "Login should fail");
        Assert.assertFalse(loginPage.isLoggedIn());
        Assert.assertTrue(loginPage.hasErrorMessage());
        Assert.assertEquals(loginPage.getErrorMessage(), 
            "Invalid email or password");
    }

    @Test(description = "Should fail login with non-existent user")
    public void shouldFailWithNonExistentUser() {
        boolean result = loginPage.login(
            "nonexistent@example.com", 
            "password123"
        );

        Assert.assertFalse(result);
        Assert.assertEquals(loginPage.getErrorMessage(), 
            "User does not exist");
    }

    @Test(description = "Should fail login with empty credentials")
    public void shouldFailWithEmptyCredentials() {
        boolean result = loginPage.login("", "");

        Assert.assertFalse(result);
        Assert.assertEquals(loginPage.getErrorMessage(), 
            "Email and password are required");
    }

    // ==================== EDGE CASES ====================

    @Test(description = "Should handle SQL injection attempts")
    public void shouldHandleSqlInjection() {
        boolean result = loginPage.login(
            "' OR '1'='1", 
            "' OR '1'='1"
        );

        Assert.assertFalse(result, "SQL injection should not succeed");
        Assert.assertEquals(loginPage.getErrorMessage(), 
            "Invalid email or password");
    }

    @Test(description = "Should handle very long input")
    public void shouldHandleVeryLongInput() {
        String longString = "a".repeat(10000);
        boolean result = loginPage.login(longString, longString);

        Assert.assertFalse(result);
        // Should not crash, should show appropriate error
    }

    @Test(description = "Should handle special characters in email")
    public void shouldHandleSpecialCharacters() {
        String specialEmail = "user+test@example.com";
        boolean result = loginPage.login(specialEmail, "password123");

        // Depending on application behavior
        // Either succeeds or shows appropriate error
        if (result) {
            Assert.assertTrue(loginPage.isLoggedIn());
        } else {
            Assert.assertTrue(loginPage.hasErrorMessage());
        }
    }

    // ==================== DATA-DRIVEN TESTS ====================

    @DataProvider(name = "invalidLoginData")
    public Object[][] getInvalidLoginData() {
        return new Object[][]{
            {validUser.getEmail(), "", "Password is required"},
            {"", validUser.getPassword(), "Email is required"},
            {"invalid-email", "password", "Invalid email format"},
            {validUser.getEmail(), "short", "Password too short"},
            {validUser.getEmail(), "incorrect", "Invalid credentials"}
        };
    }

    @Test(dataProvider = "invalidLoginData",
          description = "Data-driven test for invalid login scenarios")
    public void testInvalidLoginScenarios(String email, String password, 
                                          String expectedError) {
        loginPage.login(email, password);

        Assert.assertFalse(loginPage.isLoggedIn());
        Assert.assertTrue(loginPage.hasErrorMessage());
        Assert.assertEquals(loginPage.getErrorMessage(), expectedError);
    }

    // ==================== CLEANUP ====================

    @AfterMethod
    public void methodCleanup(ITestResult result) {
        if (!result.isSuccess()) {
            takeScreenshot(result.getName());
        }
        // Ensure logout after each test
        if (loginPage.isLoggedIn()) {
            loginPage.logout();
        }
    }
}
```

**Using Base Classes for Common Functionality:**

```java
// BaseTest.java - Common setup for all tests
public abstract class BaseTest {

    protected WebDriver driver;
    protected TestData testData;

    @BeforeSuite
    public void globalSetup() {
        // Load configuration
        Config.load("config.properties");

        // Set up reporting
        ReportManager.init();
    }

    @BeforeClass
    public void classSetup() {
        // Initialize WebDriver
        driver = WebDriverFactory.getDriver();
        driver.manage().window().maximize();

        // Load test data for this class
        testData = TestDataFactory.load(this.getClass());
    }

    @AfterClass
    public void classCleanup() {
        // Quit driver
        if (driver != null) {
            driver.quit();
        }
    }

    @AfterSuite
    public void globalCleanup() {
        // Generate reports
        ReportManager.generate();
    }

    protected void takeScreenshot(String testName) {
        // Screenshot implementation
    }
}
```

**Benefits of Good Test Class Organization:**

| Benefit | Description |
|---------|-------------|
| **Maintainability** | Changes to a feature only affect its test class |
| **Readability** | Clear structure makes tests easy to understand |
| **Reusability** | Common setup in base classes reduces duplication |
| **Parallel Execution** | Independent test classes can run in parallel |
| **Selective Execution** | Easy to run specific feature tests |
| **Reporting** | Clear grouping in test reports |
| **Onboarding** | New team members can quickly understand test organization |

**Choosing the Right Approach for Your Needs:**

TestNG offers two distinct ways to pass parameters to test methods, each with its own strengths and use cases.

| Feature | @Parameters | @DataProvider |
|---------|-------------|---------------|
| **Source** | testng.xml | Java method |
| **Data Type** | Strings only (converted) | Any Object type |
| **Number of Datasets** | Single set per test | Multiple sets |
| **Flexibility** | Static configuration | Dynamic generation |
| **External Data** | Limited to XML | Any source (Excel, DB, API) |
| **Parallel Execution** | Not directly | Built-in support |
| **Complex Data** | Difficult | Easy (objects, lists, maps) |
| **Best For** | Environment config, simple values | Data-driven testing, multiple scenarios |

**@Parameters: Simple Configuration Values**

Ideal for environment-specific settings that don't change often.

```java
public class ParameterTest {

    @Test
    @Parameters({"browser", "environment"})
    public void testWithParameters(String browser, String environment) {
        System.out.println("Running on " + browser + " in " + environment);
        // Test logic
    }
}
```

**testng.xml:**
```xml
<suite name="Parameter Suite">
    <parameter name="browser" value="chrome"/>
    <parameter name="environment" value="staging"/>

    <test name="Parameter Test">
        <classes>
            <class name="com.example.ParameterTest"/>
        </classes>
    </test>
</suite>
```

**@DataProvider: Data-Driven Testing**

Perfect for running the same test logic with multiple datasets.

```java
public class DataProviderTest {

    @DataProvider(name = "loginData")
    public Object[][] getLoginData() {
        return new Object[][]{
            {"user1@test.com", "pass123", true},
            {"user2@test.com", "wrong", false},
            {"invalid", "pass123", false},
            {"", "", false}
        };
    }

    @Test(dataProvider = "loginData")
    public void testLogin(String username, String password, boolean expected) {
        boolean result = login(username, password);
        Assert.assertEquals(result, expected);
    }
}
```

**When to Use Each:**

| Scenario | Recommended Approach |
|----------|---------------------|
| Environment configuration (URL, browser) | @Parameters |
| Test data that varies by environment | @Parameters |
| Running same test with multiple inputs | @DataProvider |
| Testing boundary conditions | @DataProvider |
| Data from Excel/CSV/database | @DataProvider |
| Complex object structures | @DataProvider |
| Parallel test execution | @DataProvider |

