import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.core.type.TypeReference;

public class JSONDataProvider {

    @DataProvider(name = "jsonData")
    public static Iterator<Object[]> getJSONData() throws IOException {
        ObjectMapper mapper = new ObjectMapper();

        List<TestData> testDataList = mapper.readValue(
            new File("src/test/resources/testdata.json"),
            new TypeReference<List<TestData>>() {}
        );

        List<Object[]> data = new ArrayList<>();
        for (TestData td : testDataList) {
            data.add(new Object[]{td});
        }

        return data.iterator();
    }
}
```

**4. Reading from Databases**

```java
public class DatabaseDataProvider {

    @DataProvider(name = "dbData")
    public static Iterator<Object[]> getDatabaseData() {
        List<Object[]> testData = new ArrayList<>();
        Connection conn = null;
        Statement stmt = null;
        ResultSet rs = null;

        try {
            // Establish database connection
            conn = DriverManager.getConnection(
                "jdbc:mysql://localhost:3306/testdb", "user", "password");

            stmt = conn.createStatement();
            rs = stmt.executeQuery(
                "SELECT username, password, expected_result, error_message FROM test_data");

            while (rs.next()) {
                TestData data = new TestData(
                    rs.getString("username"),
                    rs.getString("password"),
                    rs.getBoolean("expected_result"),
                    rs.getString("error_message")
                );
                testData.add(new Object[]{data});
            }

        } catch (SQLException e) {
            e.printStackTrace();
        } finally {
            // Close resources
            try { if (rs != null) rs.close(); } catch (SQLException e) {}
            try { if (stmt != null) stmt.close(); } catch (SQLException e) {}
            try { if (conn != null) conn.close(); } catch (SQLException e) {}
        }

        return testData.iterator();
    }
}
```

