**Mastering Essential Assertions:**

TestNG provides a comprehensive set of assertion methods. Here's a deep dive into each category with practical examples.

**1. assertEquals and assertNotEquals**

The most frequently used assertions for comparing values.

```java
public class EqualityAssertionsTest {

    @Test
    public void testEquality() {
        // Primitive types
        int actual = 5 + 3;
        Assert.assertEquals(actual, 8, "5 + 3 should equal 8");

        // Strings
        String actualString = "Hello World".toUpperCase();
        Assert.assertEquals(actualString, "HELLO WORLD", 
            "String should be uppercase");

        // With delta for floating point
        double pi = 22.0 / 7.0;
        Assert.assertEquals(pi, 3.142857, 0.001, 
            "Pi approximation should be close");

        // Objects (requires proper equals() implementation)
        User user1 = new User("john@test.com");
        User user2 = new User("john@test.com");
        Assert.assertEquals(user1, user2, 
            "Users with same email should be equal");

        // Not equal
        Assert.assertNotEquals(5, 10, "5 and 10 should not be equal");
    }

    @Test
    public void testMultipleDataTypes() {
        // Boolean
        Assert.assertEquals(true, 5 > 3);

        // Char
        Assert.assertEquals('A', 65); // ASCII comparison

        // Long
        Assert.assertEquals(1000000L, 1000L * 1000L);

        // Byte
        byte b1 = 127;
        byte b2 = 127;
        Assert.assertEquals(b1, b2);
    }
}
```

**2. assertTrue and assertFalse**

For verifying boolean conditions.

```java
public class BooleanAssertionsTest {

    @Test
    public void testBooleanConditions() {
        // Simple condition
        int age = 25;
        Assert.assertTrue(age >= 18, "User should be adult");
        Assert.assertFalse(age < 13, "User should not be a child");

        // Method calls
        List<String> list = Arrays.asList("a", "b", "c");
        Assert.assertTrue(list.contains("b"), 
            "List should contain 'b'");

        // Complex conditions
        User user = new User("john@test.com", "John", 30);
        Assert.assertTrue(
            user.isActive() && user.hasVerifiedEmail(),
            "User should be active and verified"
        );

        // String checks
        String text = "Hello World";
        Assert.assertTrue(text.startsWith("Hello"), 
            "Text should start with Hello");
        Assert.assertFalse(text.contains("Goodbye"), 
            "Text should not contain Goodbye");
    }

    @Test
    public void testWithLambda() {
        // Using lambda for complex validation
        List<Integer> numbers = Arrays.asList(1, 2, 3, 4, 5);

        Assert.assertTrue(
            numbers.stream().allMatch(n -> n > 0),
            "All numbers should be positive"
        );
    }
}
```

**3. assertNull and assertNotNull**

For verifying null/non-null values.

```java
public class NullAssertionsTest {

    private UserService userService = new UserService();

    @Test
    public void testNullChecks() {
        // Verify object exists
        User user = userService.findUserById(123);
        Assert.assertNotNull(user, 
            "User with ID 123 should exist");

        // Verify optional field is null
        Assert.assertNull(user.getMiddleName(), 
            "Middle name should be null for this user");

        // Verify error cases
        User nonExistentUser = userService.findUserById(99999);
        Assert.assertNull(nonExistentUser, 
