**8. Conditional Test Inclusion/Exclusion Patterns:**

```xml
<test name="Pattern-Based Selection">
    <classes>
        <class name="com.example.PatternTest">
            <methods>
                <!-- Include based on method name patterns -->
                <include name="test.*Valid.*"/>
                <include name=".*Success.*"/>

                <!-- Exclude based on patterns -->
                <exclude name=".*Invalid.*"/>
                <exclude name=".*Error.*"/>
                <exclude name="testSlowOperation"/>

                <!-- Conditional with BeanShell -->
                <selector>
                    <script language="beanshell">
                        <![CDATA[
                            String method = testngMethod.getMethodName();
                            // Only run methods with "Fast" in name when in CI
                            if (method.contains("Fast") && 
                                System.getProperty("ci") != null) {
                                return true;
                            }
                            // Always run smoke tests
                            if (method.startsWith("testSmoke")) {
                                return true;
                            }
                            return false;
                        ]]>
                    </script>
                </selector>
            </methods>
        </class>
    </classes>
</test>
```

**9. Skip Based on Test Dependencies:**

```xml
<test name="Dependency-Based Skip">
    <groups>
        <dependencies>
            <!-- If login group fails, skip all checkout tests -->
            <group name="checkout" depends-on="login"/>
            <group name="payment" depends-on="checkout"/>
        </dependencies>
    </groups>

    <packages>
        <package name="com.example.tests.checkout.*"/>
    </packages>
</test>
```

**10. Complete Example with Multiple Skip Conditions:**

```xml
<suite name="Smart Skip Suite">
    <parameter name="environment" value="staging"/>
    <parameter name="browser" value="chrome"/>

    <test name="Conditional Test Execution">
        <method-selectors>
            <!-- First selector: Environment-based -->
            <method-selector>
                <script language="beanshell">
                    <![CDATA[
                        String env = System.getProperty("environment", "dev");
                        String method = testngMethod.getMethodName();

                        // Skip destructive tests in production
                        if (env.equals("production") && 
                            (method.contains("Delete") || method.contains("Update"))) {
                            return false;
                        }
                        return true;
                    ]]>
                </script>
            </method-selector>

            <!-- Second selector: Browser-based -->
            <method-selector>
                <script language="beanshell">
                    <![CDATA[
                        String browser = System.getProperty("browser", "chrome");
                        String method = testngMethod.getMethodName();

                        // Skip Safari-specific tests on other browsers
                        if (method.contains("SafariOnly") && !browser.equals("safari")) {
                            return false;
                        }
                        return true;
                    ]]>
                </script>
            </method-selector>

            <!-- Third selector: Feature flag based -->
            <method-selector>
                <script language="beanshell">
                    <![CDATA[
                        // Assuming you have a system property for feature flags
                        String featureFlags = System.getProperty("features", "");
                        String method = testngMethod.getMethodName();

                        // Skip tests for disabled features
                        if (method.contains("NewPayment") && 
                            !featureFlags.contains("new-payment")) {
                            return false;
                        }
                        return true;
                    ]]>
                </script>
            </method-selector>
        </method-selectors>

        <packages>
            <package name="com.example.tests.*"/>
        </packages>
    </test>
</suite>
```

**Skip Conditions Summary:**

| Skip Method | Use Case | Example |
|-------------|----------|---------|
| `enabled="false"` | Permanent disable | `<test enabled="false">` |
| Method exclude | Skip specific methods | `<exclude name="testBroken"/>` |
| BeanShell | Complex conditions | `<script language="beanshell">` |
| SkipException | Runtime decision | `throw new SkipException()` |
| Custom annotation | Reusable conditions | `@SkipIf(condition)` |
| Group dependencies | Conditional on other tests | `<group depends-on>` |
| System properties | Environment-based | `System.getProperty("env")` |

