<suite name="Optimized Parallel Suite" 
      verbose="1"
      parallel="tests" 
      thread-count="4"
      configfailurepolicy="continue"
      time-out="60000"
      data-provider-thread-count="5"
      preserve-order="false">

    <!-- Use test-level parallelism for better control -->
    <test name="Fast Tests" parallel="methods" thread-count="8">
        <groups>
            <run>
                <include name="fast"/>
            </run>
        </groups>
        <packages>
