import org.testng.*;
import java.util.*;

public class TestExecutionListener implements ITestListener {

    private Map<String, Long> testStartTimes = new HashMap<>();
    private int passedTests = 0;
    private int failedTests = 0;
    private int skippedTests = 0;

    @Override
    public void onTestStart(ITestResult result) {
        String testName = result.getName();
        testStartTimes.put(testName, System.currentTimeMillis());

        System.out.println("==================================================================");
        System.out.println("Starting test: " + testName);
        System.out.println("Class: " + result.getTestClass().getName());
        System.out.println("Description: " + result.getMethod().getDescription());

        // Log parameters if any
        Object[] parameters = result.getParameters();
        if (parameters != null && parameters.length > 0) {
            System.out.println("Parameters: " + Arrays.toString(parameters));
        }
    }

    @Override
    public void onTestSuccess(ITestResult result) {
        passedTests++;
        long duration = System.currentTimeMillis() - testStartTimes.get(result.getName());

        System.out.println("✅ Test PASSED: " + result.getName());
        System.out.println("Duration: " + duration + " ms");
        System.out.println("==================================================================");
    }

    @Override
    public void onTestFailure(ITestResult result) {
        failedTests++;
        long duration = System.currentTimeMillis() - testStartTimes.get(result.getName());

        System.out.println("❌ Test FAILED: " + result.getName());
        System.out.println("Duration: " + duration + " ms");
        System.out.println("Error: " + result.getThrowable().getMessage());
        result.getThrowable().printStackTrace();
        System.out.println("==================================================================");
    }

    @Override
    public void onTestSkipped(ITestResult result) {
        skippedTests++;

        System.out.println("⚠️ Test SKIPPED: " + result.getName());
        if (result.getThrowable() != null) {
            System.out.println("Reason: " + result.getThrowable().getMessage());
        }
        System.out.println("==================================================================");
    }

    @Override
    public void onTestFailedButWithinSuccessPercentage(ITestResult result) {
        System.out.println("Test partially passed: " + result.getName());
    }

    @Override
    public void onStart(ITestContext context) {
        System.out.println("\n\n");
        System.out.println("========================================");
        System.out.println("STARTING TEST SUITE: " + context.getName());
        System.out.println("Start time: " + new Date(context.getStartDate().getTime()));
        System.out.println("========================================");

        // Reset counters
        passedTests = 0;
        failedTests = 0;
        skippedTests = 0;
        testStartTimes.clear();
    }

    @Override
    public void onFinish(ITestContext context) {
        System.out.println("\n\n");
        System.out.println("========================================");
        System.out.println("FINISHED TEST SUITE: " + context.getName());
        System.out.println("End time: " + new Date(context.getEndDate().getTime()));
        System.out.println("Duration: " + (context.getEndDate().getTime() - context.getStartDate().getTime()) + " ms");
        System.out.println("\nTest Summary:");
        System.out.println("  Total: " + context.getAllTestMethods().length);
        System.out.println("  Passed: " + passedTests);
        System.out.println("  Failed: " + failedTests);
        System.out.println("  Skipped: " + skippedTests);
        System.out.println("========================================");
    }
}
