import org.openqa.selenium.io.FileHandler;
import java.io.File;
import java.text.SimpleDateFormat;
import java.util.Date;

public class ScreenshotListener extends TestExecutionListener {

    private static final String SCREENSHOT_DIR = "test-output/screenshots";
    private ThreadLocal<WebDriver> driverThreadLocal = new ThreadLocal<>();

    public void setDriver(WebDriver driver) {
        driverThreadLocal.set(driver);
    }

    @Override
    public void onTestFailure(ITestResult result) {
        super.onTestFailure(result);

        WebDriver driver = driverThreadLocal.get();
        if (driver != null) {
            captureScreenshot(result);
        }
    }

    private void captureScreenshot(ITestResult result) {
        try {
            WebDriver driver = driverThreadLocal.get();

            // Create screenshot directory if it doesn't exist
            File screenshotDir = new File(SCREENSHOT_DIR);
            if (!screenshotDir.exists()) {
                screenshotDir.mkdirs();
            }

            // Generate filename with timestamp
            String timestamp = new SimpleDateFormat("yyyyMMdd_HHmmss").format(new Date());
            String className = result.getTestClass().getName();
            String methodName = result.getName();
            String filename = String.format("%s/%s_%s_%s.png", 
                SCREENSHOT_DIR, className, methodName, timestamp);

            // Take screenshot
            File screenshot = ((TakesScreenshot) driver).getScreenshotAs(OutputType.FILE);
            FileHandler.copy(screenshot, new File(filename));

            System.out.println("📸 Screenshot saved: " + filename);

            // Add screenshot path to report
            Reporter.log("<a href='" + filename + "'>Screenshot</a>");

        } catch (Exception e) {
            System.err.println("Failed to capture screenshot: " + e.getMessage());
        }
    }

    @Override
    public void onTestSuccess(ITestResult result) {
        super.onTestSuccess(result);
        // Optional: capture screenshot on success as well
        // captureScreenshot(result);
    }
}
