**Simple Custom Reporter:**

```java
import org.testng.*;
import java.io.*;
import java.util.*;

public class SimpleCustomReporter implements IReporter {

    @Override
    public void generateReport(List<XmlSuite> xmlSuites, List<ISuite> suites,
                               String outputDirectory) {

        try (PrintWriter writer = new PrintWriter(
                new File(outputDirectory + "/custom-report.html"))) {

            writer.println("<!DOCTYPE html>");
            writer.println("<html>");
            writer.println("<head><title>Custom Test Report</title>");
            writer.println("<style>");
            writer.println("body { font-family: Arial; margin: 20px; }");
            writer.println(".pass { color: green; }");
            writer.println(".fail { color: red; }");
            writer.println(".skip { color: orange; }");
            writer.println("table { border-collapse: collapse; width: 100%; }");
            writer.println("th, td { border: 1px solid #ddd; padding: 8px; }");
            writer.println("th { background-color: #f2f2f2; }");
            writer.println("</style></head><body>");

            writer.println("<h1>Custom Test Report</h1>");

            // Summary section
            int totalTests = 0;
            int passedTests = 0;
            int failedTests = 0;
            int skippedTests = 0;

            for (ISuite suite : suites) {
                Map<String, ISuiteResult> results = suite.getResults();
                for (ISuiteResult result : results.values()) {
                    ITestContext context = result.getTestContext();
                    passedTests += context.getPassedTests().size();
                    failedTests += context.getFailedTests().size();
                    skippedTests += context.getSkippedTests().size();
                }
            }
            totalTests = passedTests + failedTests + skippedTests;

            writer.println("<h2>Summary</h2>");
            writer.println("<table>");
            writer.println("<tr><th>Total</th><td>" + totalTests + "</td></tr>");
            writer.println("<tr><th>Passed</th><td class='pass'>" + passedTests + "</td></tr>");
            writer.println("<tr><th>Failed</th><td class='fail'>" + failedTests + "</td></tr>");
            writer.println("<tr><th>Skipped</th><td class='skip'>" + skippedTests + "</td></tr>");
            writer.println("</table>");

            // Detailed results
            writer.println("<h2>Detailed Results</h2>");

            for (ISuite suite : suites) {
                writer.println("<h3>Suite: " + suite.getName() + "</h3>");

                Map<String, ISuiteResult> results = suite.getResults();
                for (ISuiteResult result : results.values()) {
                    ITestContext context = result.getTestContext();

                    writer.println("<h4>Test: " + context.getName() + "</h4>");

                    // Passed tests
                    if (!context.getPassedTests().isEmpty()) {
                        writer.println("<h5 class='pass'>Passed Tests</h5>");
                        writer.println("<table>");
                        writer.println("<tr><th>Method</th><th>Duration (ms)</th></tr>");

                        for (ITestResult testResult : context.getPassedTests().getAllResults()) {
                            writer.println("<tr>");
                            writer.println("<td>" + testResult.getName() + "</td>");
                            writer.println("<td>" + (testResult.getEndMillis() - testResult.getStartMillis()) + "</td>");
                            writer.println("</tr>");
                        }
                        writer.println("</table>");
                    }

                    // Failed tests
                    if (!context.getFailedTests().isEmpty()) {
                        writer.println("<h5 class='fail'>Failed Tests</h5>");
                        writer.println("<table>");
                        writer.println("<tr><th>Method</th><th>Error</th></tr>");

                        for (ITestResult testResult : context.getFailedTests().getAllResults()) {
                            writer.println("<tr>");
                            writer.println("<td>" + testResult.getName() + "</td>");
                            writer.println("<td>" + testResult.getThrowable().getMessage() + "</td>");
                            writer.println("</tr>");
                        }
                        writer.println("</table>");
                    }
                }
            }

            writer.println("</body></html>");

        } catch (IOException e) {
            e.printStackTrace();
        }
    }
}
