            extentTest.info("Verifying successful login");
            Assert.assertTrue(loginPage.isLoggedIn(), "User should be logged in");

            // Add screenshot on success as well
            File screenshot = ((TakesScreenshot) driver).getScreenshotAs(OutputType.FILE);
            String path = "screenshots/success_" + System.currentTimeMillis() + ".png";
            FileHandler.copy(screenshot, new File(path));
            extentTest.addScreenCaptureFromPath(path);

        } catch (Exception e) {
            // Take screenshot on failure
            File screenshot = ((TakesScreenshot) driver).getScreenshotAs(OutputType.FILE);
            String path = "screenshots/failure_" + System.currentTimeMillis() + ".png";
            FileHandler.copy(screenshot, new File(path));
            extentTest.addScreenCaptureFromPath(path);

            throw e;
        }
    }

    @Test(description = "Test API endpoint with logging")
