```groovy
stage('Quality Gate') {
    steps {
        script {
            // Parse test results
            def testResults = readFile('target/surefire-reports/testng-results.xml')

            // Count failures by group
            def criticalFailures = sh(
                script: "grep -c 'testng:group=\"critical\".*status=\"FAIL\"' target/surefire-reports/testng-results.xml || true",
                returnStdout: true
            ).trim().toInteger()

            def totalFailures = sh(
                script: "grep -c 'status=\"FAIL\"' target/surefire-reports/testng-results.xml || true",
                returnStdout: true
            ).trim().toInteger()

            echo "Critical failures: ${criticalFailures}"
            echo "Total failures: ${totalFailures}"

            // Quality gate rules
            if (criticalFailures > 0) {
                error("Quality Gate failed: ${criticalFailures} critical test failures")
            }

            if (totalFailures > 5) {
                unstable("Warning: ${totalFailures} test failures detected")
            }

            // Check pass rate
            def totalTests = sh(
                script: "grep -c '<test-method' target/surefire-reports/testng-results.xml || true",
                returnStdout: true
            ).trim().toInteger()

            def passRate = ((totalTests - totalFailures) * 100.0 / totalTests)
            echo "Pass rate: ${passRate}%"

            if (passRate < 90) {
                error("Quality Gate failed: Pass rate ${passRate}% < 90%")
            }
        }
    }
}
