                        mvn clean test \
                            -Dgroups=integration \
                            -Dservice-a.url=http://service-a:8080 \
                            -Dservice-b.url=http://service-b:8080 \
                            -Denvironment=${TEST_ENV}
                    """
                }
            }
            post {
                always {
                    junit 'tests/integration/target/surefire-reports/*.xml'
                }
            }
        }

        stage('End-to-End Tests') {
            agent { label 'test-runner' }
            when { branch 'main' }
            steps {
                dir('tests/e2e') {
                    sh """
                        mvn clean test \
                            -Dgroups=e2e,critical \
                            -Dapp.url=https://staging.company.com \
                            -Dbrowser=chrome \
                            -Dheadless=true
                    """
                }
            }
            post {
                always {
                    junit 'tests/e2e/target/surefire-reports/*.xml'
                    publishHTML([
                        reportDir: 'tests/e2e/target/surefire-reports',
                        reportFiles: 'index.html',
                        reportName: 'E2E Test Report'
                    ])
                }
            }
        }
    }

    post {
        always {
            // Aggregate all reports
            step([$class: 'TestNGPublisher', 
                  testNGResults: ['**/target/surefire-reports/testng-results.xml']])

            // Send summary to Slack
            def summary = createTestSummary()
            slackSend(
                color: currentBuild.result == 'SUCCESS' ? 'good' : 'danger',
                message: "${currentBuild.result}: ${env.JOB_NAME} #${env.BUILD_NUMBER}\n${summary}",
                channel: '#ci-cd'
            )
        }

        failure {
            // Trigger rollback if tests fail
            sh 'kubectl rollout undo deployment/service-a'
            sh 'kubectl rollout undo deployment/service-b'
        }
    }
}

def createTestSummary() {
    def summary = ""
    def reports = findFiles(glob: '**/target/surefire-reports/testng-results.xml')

    reports.each { report ->
        def content = readFile(report.path)
        def total = (content =~ /<test-method/).size()
        def failed = (content =~ /status="FAIL"/).size()
        def skipped = (content =~ /status="SKIP"/).size()
        def passed = total - failed - skipped

        def serviceName = report.path.split('/')[0]
        summary += "${serviceName}: ${passed}/${total} passed"
        if (failed > 0) {
            summary += " (${failed} failed)"
        }
        summary += "\n"
    }

    return summary
}
```

