                    "Failures: ${result.failedTestCount}, " +
                    "Skipped: ${result.skippedTestCount}"
                println "Time: ${(result.endTime - result.startTime) / 1000}s\n"
            }
        }
    }

    // Test system properties
    systemProperties = [
        'environment': System.getProperty('environment', 'test'),
        'browser': System.getProperty('browser', 'chrome'),
        'headless': System.getProperty('headless', 'true'),
        'timeout': System.getProperty('timeout', '5000')
    ]

    // Fail fast option
    failFast = System.getProperty('failFast', 'false') == 'true'

    // Test reports
    reports {
        html.required = true
        junitXml.required = true
    }

    // Ignore failures? (for CI)
    ignoreFailures = System.getProperty('ignoreFailures', 'false') == 'true'

    // Max parallel forks
    maxParallelForks = Runtime.runtime.availableProcessors()
}

// JaCoCo for code coverage
jacoco {
    toolVersion = '0.8.11'
    reportsDirectory = layout.buildDirectory.dir('reports/jacoco')
}

jacocoTestReport {
    dependsOn test
    reports {
        xml.required = true
        csv.required = true
        html.required = true
        xml.outputLocation = layout.buildDirectory.file('reports/jacoco/jacoco.xml')
        html.outputLocation = layout.buildDirectory.dir('reports/jacoco/html')
    }
}

jacocoTestCoverageVerification {
    violationRules {
        rule {
            limit {
                minimum = 0.8  // 80% coverage required
            }
        }

        rule {
            enabled = true
            element = 'CLASS'
            includes = ['com.example.*']

            limit {
                counter = 'LINE'
                value = 'COVEREDRATIO'
                minimum = 0.8
            }

            limit {
                counter = 'BRANCH'
                value = 'COVEREDRATIO'
                minimum = 0.7
            }
        }
    }
}

// Custom tasks for different test types
task unitTest(type: Test) {
    useJUnitPlatform()
    filter {
        includeTestsMatching '*UnitTest'
    }
    systemProperties = System.properties
}

task integrationTest(type: Test) {
    useJUnitPlatform()
    filter {
        includeTestsMatching '*IntegrationTest'
    }
    systemProperties = System.properties
}

task smokeTest(type: Test) {
    useJUnitPlatform()
    filter {
        includeTestsMatching '*SmokeTest'
    }
    systemProperties = System.properties
}

// Ensure tasks run in correct order
check.dependsOn jacocoTestCoverageVerification
build.dependsOn test
```

**Usage Examples:**

```bash
