gradle test

# Run unit tests only
gradle unitTest

# Run integration tests with custom environment
gradle integrationTest -Denvironment=staging

# Run tests in parallel with 8 threads
gradle test -Djunit.jupiter.execution.parallel.config.fixed.parallelism=8

# Generate test report
gradle test

# Generate coverage report
gradle jacocoTestReport

# Check coverage thresholds
gradle jacocoTestCoverageVerification
```

