**6. Error Handling in Parameterized Tests**

```java
class ErrorHandlingTest {

    @ParameterizedTest
    @CsvSource({
        "1, 1, 2",
        "2, 2, 4",
        "invalid, 2, 0"  // This will cause NumberFormatException
    })
    void testWithInvalidData(String a, String b, int expected) {
        // Test will fail with clear error
        assertThrows(NumberFormatException.class, () -> {
            int intA = Integer.parseInt(a);
            int intB = Integer.parseInt(b);
            assertEquals(expected, intA + intB);
        });
    }

    @ParameterizedTest
    @MethodSource("safeDataProvider")
    void testWithSafeData(String a, String b, Integer expected) {
        try {
            int intA = Integer.parseInt(a);
            int intB = Integer.parseInt(b);
            assertEquals(expected, intA + intB);
        } catch (NumberFormatException e) {
            // Log and skip, but test should be designed better
            System.err.println("Invalid number format: " + a + " or " + b);
        }
    }
}
