task smokeTest(type: Test) {
    useJUnitPlatform()
    filter {
        includeTestsMatching 'SmokeTestSuite'
    }
}

task regressionTest(type: Test) {
    useJUnitPlatform()
    filter {
        includeTestsMatching 'RegressionTestSuite'
    }
}

task fullTest(type: Test) {
    useJUnitPlatform()
    filter {
        includeTestsMatching '*TestSuite'
    }
}
```

