```groovy
stage('Quality Gate') {
    steps {
        script {
            // Parse test results
            def testResults = readFile('target/surefire-reports/TEST-com.example.Test.xml')

            // Count failures
            def failures = sh(
                script: "grep -c 'failures=\"1\"' target/surefire-reports/*.xml || true",
                returnStdout: true
            ).trim().toInteger()

            def errors = sh(
                script: "grep -c 'errors=\"1\"' target/surefire-reports/*.xml || true",
                returnStdout: true
            ).trim().toInteger()

            def totalFailures = failures + errors

            echo "Total failures: ${totalFailures}"

            // Quality gate rules
            if (totalFailures > 0) {
                // Check if any critical tests failed
                def criticalFailures = sh(
                    script: "grep -l '@Tag.*critical.*' target/surefire-reports/*.xml | xargs grep -l 'failures=\"1\"' || true",
                    returnStdout: true
                ).trim()

                if (criticalFailures) {
                    error("Quality Gate failed: Critical tests failed")
                } else {
                    unstable("Warning: ${totalFailures} non-critical test failures")
                }
            }
        }
    }
}
